async fn handle_create_session(
    request_id: u64,
    state: &ServerState,
    writer: &SharedWriter,
    name: Option<String>,
    working_directory: PathBuf,
) -> Result<(), ServerError> {
    let session = state
        .sessions
        .create_session(name, working_directory)
        .await?;
    state
        .session_catalog
        .upsert_native_session(session.clone())
        .await;
    if let Ok(mut events) = state
        .sessions
        .session_events_range(session.id, 0, 0, 1)
        .await
        && let Some(event) = events.pop()
    {
        publish_session_event(state, &event).await;
    }
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::SessionCreated { session }),
    )
    .await
}

async fn handle_list_sessions(
    request_id: u64,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    working_directory: &Path,
) -> Result<(), ServerError> {
    let snapshot = state
        .session_catalog
        .snapshot(state, working_directory)
        .await;
    let snapshot = if matches!(snapshot.status, SessionCatalogStatus::Loading) {
        state
            .sessions
            .wait_catalog_loaded()
            .await
            .map_err(ServerError::SessionStore)?;
        state.session_catalog.refresh_native_now(state).await;
        state
            .session_catalog
            .snapshot(state, working_directory)
            .await
    } else {
        snapshot
    };
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::SessionList {
            sessions: snapshot.sessions,
            catalog_status: snapshot.status,
            catalog_sources: snapshot.sources,
            catalog_revision: snapshot.revision,
        }),
    )
    .await
}

