/// Handle an explicit full-history request.
///
/// This endpoint performs a complete canonical event read and is intended only for
/// export/debug/history commands. Normal UI, attach, prompt/model-context, catalog,
/// and maintenance flows must use bounded pages, projection windows, or typed read models.
async fn handle_session_history(
    request_id: u64,
    client_id: ClientId,
    state: &ServerState,
    writer: &SharedWriter,
    session_id: SessionId,
) -> Result<(), ServerError> {
    if let Some(active_namespace) = state
        .active_session_namespace_mismatch(session_id, client_id)
        .await
    {
        return send_incompatible_active_session_response(writer, request_id, &active_namespace)
            .await;
    }
    match state.sessions.session_history(session_id).await {
        Ok(history) => {
            send_response(
                writer,
                request_id,
                Response::Ok(ResponsePayload::SessionHistory {
                    session_id,
                    history,
                }),
            )
            .await
        }
        Err(error) => {
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await
        }
    }
}

const MAX_SESSION_OPEN_PROGRESS_WAIT: Duration = Duration::from_secs(5);

fn migrating_session_open_snapshot(
    session_id: SessionId,
    writer_epoch: u32,
) -> bcode_session_models::SessionOpenOperationSnapshot {
    bcode_session_models::SessionOpenOperationSnapshot {
        operation_id: bcode_session_models::SessionOpenOperationId::new(),
        revision: 0,
        session_id,
        source_writer_epoch: Some(u64::from(writer_epoch)),
        target_writer_epoch: u64::from(bcode_session::db::CURRENT_SESSION_STORAGE_WRITER_EPOCH),
        progress: bcode_session_models::SessionMigrationProgress {
            stage: bcode_session_models::SessionMigrationStage::WaitingForOwnership,
            completed_units: None,
            total_units: None,
            unit: None,
            message: "Waiting for exclusive session ownership".to_owned(),
        },
        outcome: None,
        backup_path: None,
    }
}

fn session_migration_failure_outcome(
    error: &bcode_session::SessionError,
) -> bcode_session_models::SessionOpenTerminalOutcome {
    use bcode_session_models::{SessionOpenFailureKind, SessionOpenTerminalOutcome};
    match error {
        bcode_session::SessionError::Db(
            bcode_session::db::SessionDbError::WriterIncompatible { actual, expected },
        ) => SessionOpenTerminalOutcome::WriterIncompatible {
            actual: *actual,
            expected: *expected,
        },
        bcode_session::SessionError::ProjectionStale { .. }
        | bcode_session::SessionError::Db(
            bcode_session::db::SessionDbError::InvalidCanonicalSequence { .. }
            | bcode_session::db::SessionDbError::InvalidRow { .. }
            | bcode_session::db::SessionDbError::PersistedEvent(_),
        ) => SessionOpenTerminalOutcome::RepairRequired {
            reason: error.to_string(),
        },
        bcode_session::SessionError::NotFound(_) => SessionOpenTerminalOutcome::Failed {
            kind: SessionOpenFailureKind::NotFound,
            message: error.to_string(),
            backup_path: None,
        },
        bcode_session::SessionError::MigrationBackup { .. } => SessionOpenTerminalOutcome::Failed {
            kind: SessionOpenFailureKind::BackupFailed,
            message: error.to_string(),
            backup_path: None,
        },
        bcode_session::SessionError::Lease(
            bcode_session::lease::SessionLeaseError::OwnedByOtherDaemon { .. },
        ) => SessionOpenTerminalOutcome::Failed {
            kind: SessionOpenFailureKind::OwnedByOtherDaemon,
            message: error.to_string(),
            backup_path: None,
        },
        _ => SessionOpenTerminalOutcome::Failed {
            kind: SessionOpenFailureKind::MigrationFailed,
            message: error.to_string(),
            backup_path: None,
        },
    }
}

async fn current_writer_with_released_historical_events(
    state: &ServerState,
    session_id: SessionId,
    source_writer_epoch: Option<u32>,
) -> Option<u32> {
    if source_writer_epoch.is_some() {
        return source_writer_epoch;
    }
    let root = state.sessions.session_store_root()?;
    let db = bcode_session::db::SessionDb::open_existing_turso_in_root(session_id, &root)
        .await
        .ok()?;
    let schema = db.first_non_current_event_schema().await.ok()??;
    bcode_session_migration::is_released_historical_event_schema(schema)
        .then_some(bcode_session::db::CURRENT_SESSION_STORAGE_WRITER_EPOCH)
}

async fn handle_prepare_session_open(
    request_id: u64,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    session_id: SessionId,
) -> Result<(), ServerError> {
    let source_writer_epoch = match state.sessions.session_health(session_id).await {
        bcode_session::SessionHealth::Migratable { source, .. }
        | bcode_session::SessionHealth::BlockedOwner { source, .. }
        | bcode_session::SessionHealth::WriterIncompatible {
            actual: Some(source),
            ..
        } => u32::try_from(source).ok(),
        _ => None,
    };
    let source_writer_epoch =
        current_writer_with_released_historical_events(state, session_id, source_writer_epoch)
            .await;
    if let Some(source_writer_epoch) = source_writer_epoch {
        if let Err(error) = state.session_migrations.plan(source_writer_epoch) {
            return send_response(
                writer,
                request_id,
                Response::Err(ErrorResponse::new(
                    "session_writer_incompatible",
                    error.to_string(),
                )),
            )
            .await;
        }
        let initial = migrating_session_open_snapshot(session_id, source_writer_epoch);
        let sessions = state.sessions.clone();
        let operation = state
            .session_migrations
            .operations()
            .start_or_join(initial, move |operation| async move {
                let reporter =
                    bcode_session_migration::SessionMigrationProgressReporter::new(operation);
                let result = async {
                    let root = sessions
                        .session_store_root()
                        .ok_or(bcode_session::SessionError::NotFound(session_id))?;
                    let lease_owner = sessions
                        .session_lease_owner()
                        .ok_or(bcode_session::SessionError::NotFound(session_id))?;
                    let lease = session_migration_execution::migrate_owned_session_storage(
                        session_id,
                        &root,
                        u64::from(source_writer_epoch),
                        &reporter,
                        &bcode_metrics::MetricsRegistry::disabled(),
                        &lease_owner,
                    )
                    .await?;
                    sessions.adopt_session_lease(session_id, lease).await?;
                    sessions.load_current_session(session_id).await
                }
                .await;
                match result {
                    Ok(()) => bcode_session_models::SessionOpenTerminalOutcome::Ready,
                    Err(error) => session_migration_failure_outcome(&error),
                }
            })
            .await;
        return send_response(
            writer,
            request_id,
            Response::Ok(ResponsePayload::SessionOpenPrepared {
                snapshot: operation.snapshot(),
            }),
        )
        .await;
    }
    match state.sessions.prepare_session_open(session_id).await {
        Ok(snapshot) => {
            send_response(
                writer,
                request_id,
                Response::Ok(ResponsePayload::SessionOpenPrepared { snapshot }),
            )
            .await
        }
        Err(error) => {
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn handle_wait_session_open_progress(
    request_id: u64,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    session_id: SessionId,
    operation_id: bcode_session_models::SessionOpenOperationId,
    after_revision: u64,
    timeout_ms: u64,
) -> Result<(), ServerError> {
    let Some(mut receiver) = state
        .session_migrations
        .subscribe(session_id, operation_id)
        .await
    else {
        return send_response(
            writer,
            request_id,
            Response::Err(ErrorResponse::new(
                "session_open_operation_not_found",
                format!(
                    "session-open operation {operation_id} does not belong to session {session_id}"
                ),
            )),
        )
        .await;
    };
    let snapshot = wait_session_open_snapshot(&mut receiver, after_revision, timeout_ms).await;
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::SessionOpenPrepared { snapshot }),
    )
    .await
}

async fn wait_session_open_snapshot(
    receiver: &mut tokio::sync::watch::Receiver<bcode_session_models::SessionOpenOperationSnapshot>,
    after_revision: u64,
    timeout_ms: u64,
) -> bcode_session_models::SessionOpenOperationSnapshot {
    let current = receiver.borrow_and_update().clone();
    if current.revision > after_revision || current.outcome.is_some() {
        return current;
    }
    let timeout = Duration::from_millis(timeout_ms).min(MAX_SESSION_OPEN_PROGRESS_WAIT);
    let _ = tokio::time::timeout(timeout, receiver.changed()).await;
    receiver.borrow_and_update().clone()
}

