async fn handle_session_search(
    request_id: u64,
    state: &ServerState,
    writer: &SharedWriter,
    request: bcode_session_search::SessionSearchRequest,
    policy: bcode_session_search::SessionSearchPlanPolicy,
    routes: Vec<bcode_session_search::SessionSearchContentRoute>,
    hydrate: bool,
) -> Result<(), ServerError> {
    match session_search::search_federated_with_policy_and_routes(state, &request, &policy, &routes)
        .await
    {
        Ok(mut response) => {
            let hydrated_hits = if hydrate {
                let started = std::time::Instant::now();
                let hydrated = session_search::hydrate_hits(state, response.hits.clone()).await;
                session_search::report_hydration_outcomes(
                    &mut response,
                    &hydrated,
                    u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX),
                );
                hydrated
            } else {
                Vec::new()
            };
            send_response(
                writer,
                request_id,
                Response::Ok(ResponsePayload::SessionSearch {
                    response,
                    hydrated_hits,
                }),
            )
            .await
        }
        Err(error) => {
            send_response(
                writer,
                request_id,
                Response::Err(ErrorResponse::new(
                    format!("session_search_{:?}", error.code).to_lowercase(),
                    error.message,
                )),
            )
            .await
        }
    }
}

