fn server_session_error_response(error: &ServerError) -> ErrorResponse {
    match error {
        ServerError::Session(error) => session_error_response(error),
        ServerError::SessionDb(error) => session_db_error_response(error),
        _ => ErrorResponse::new("session_unavailable", error.to_string()),
    }
}

const fn ownership_recovery_guidance() -> &'static str {
    "ownership normally releases automatically after the final client disconnects and session work becomes quiescent; `bcode session release-owner <session-id>` requests non-destructive explicit release and reports blockers; `bcode session stop-owner <session-id>` requests verified graceful daemon shutdown; use `bcode session kill-owner <session-id>` only as a reviewed last resort after identity verification"
}

fn session_error_response(error: &bcode_session::SessionError) -> ErrorResponse {
    match error {
        bcode_session::SessionError::Lease(
            bcode_session::lease::SessionLeaseError::OwnedByOtherDaemon { .. },
        ) => ErrorResponse::new(
            "session_active_elsewhere",
            format!("{error}; {}", ownership_recovery_guidance()),
        ),
        bcode_session::SessionError::ProjectionStale { .. } => {
            ErrorResponse::new("projection_stale", error.to_string())
        }
        bcode_session::SessionError::StorageMigrationRequired { .. } => {
            ErrorResponse::new("session_migration_required", error.to_string())
        }
        bcode_session::SessionError::Db(db_error) => session_db_error_response(db_error),
        bcode_session::SessionError::NotFound(_) => {
            ErrorResponse::new("session_not_found", error.to_string())
        }
        _ => ErrorResponse::new("session_unavailable", error.to_string()),
    }
}

fn session_db_error_response(error: &bcode_session::db::SessionDbError) -> ErrorResponse {
    match error {
        bcode_session::db::SessionDbError::PersistedEvent(
            bcode_session::persisted::PersistedSessionEventError::UnsupportedSchemaVersion {
                actual,
                current,
            },
        ) => ErrorResponse::new(
            "session_format_incompatible",
            format!(
                "session history uses event schema {actual}, but this Bcode build supports through schema {current}; upgrade Bcode and restart the daemon, then reopen the session"
            ),
        ),
        bcode_session::db::SessionDbError::PersistedEvent(
            bcode_session::persisted::PersistedSessionEventError::UnsupportedEventKind { kind },
        ) => ErrorResponse::new(
            "session_format_incompatible",
            format!(
                "session history contains unsupported persisted event kind {kind}; upgrade Bcode and restart the daemon, then reopen the session"
            ),
        ),
        bcode_session::db::SessionDbError::WriterIncompatible { .. } => {
            ErrorResponse::new("session_writer_incompatible", error.to_string())
        }
        _ if error.is_lock_error() => ErrorResponse::new(
            "session_database_locked",
            format!("{error}; {}", ownership_recovery_guidance()),
        ),
        bcode_session::db::SessionDbError::ProjectionIncompatible { .. }
        | bcode_session::db::SessionDbError::ProjectionStale { .. }
        | bcode_session::db::SessionDbError::ModelContextProjectionVersion { .. }
        | bcode_session::db::SessionDbError::ModelContextProjectionStale { .. } => {
            ErrorResponse::new("projection_stale", error.to_string())
        }
        bcode_session::db::SessionDbError::HistoryReadLimitExceeded { .. } => {
            ErrorResponse::new("session_history_limit_exceeded", error.to_string())
        }
        bcode_session::db::SessionDbError::MigrationHistoryIncompatible { .. }
        | bcode_session::db::SessionDbError::InvalidCanonicalSequence { .. }
        | bcode_session::db::SessionDbError::InvalidRow { .. } => {
            ErrorResponse::new("session_repair_required", error.to_string())
        }
        _ if database_error_requires_repair(error) => {
            ErrorResponse::new("session_repair_required", error.to_string())
        }
        _ => ErrorResponse::new("session_unavailable", error.to_string()),
    }
}

fn database_error_requires_repair(error: &bcode_session::db::SessionDbError) -> bool {
    let message = error.to_string().to_ascii_lowercase();
    message.contains("short read on wal frame")
        || message.contains("database disk image is malformed")
        || message.contains("file is not a database")
}

async fn handle_attach_session(
    request_id: u64,
    client_id: ClientId,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    attached_session: &mut Option<SessionId>,
    session_id: SessionId,
) -> Result<(), ServerError> {
    recover_abandoned_session_runtime_work_best_effort(state, session_id).await;
    let client_namespace = state.client_session_namespace(client_id).await;
    if let Err(active_namespace) = state
        .try_activate_session_namespace(session_id, client_namespace)
        .await
    {
        return send_incompatible_active_session_response(writer, request_id, &active_namespace)
            .await;
    }
    match state.sessions.attach_session(session_id, client_id).await {
        Ok(attachment) => {
            state.complete_session_namespace_attach(session_id).await;
            restore_active_skills_from_history(&attachment.history, state, session_id).await;
            *attached_session = Some(session_id);
            state.attach_client_session(client_id, session_id).await;
            let draft = state.sessions.session_composer_draft(session_id).await?;
            send_response(
                writer,
                request_id,
                Response::Ok(ResponsePayload::Attached {
                    session_id,
                    session: attachment.session,
                    history: compact_attach_history(attachment.history),
                    input_history: attachment.input_history,
                    import_warnings: Vec::new(),
                    draft,
                    runtime_selection: session_runtime_selection_payload(state, session_id).await,
                    projection_window: None,
                }),
            )
            .await?;
            let sink = ClientEventSink::new(client_id, writer.clone(), state.metrics.clone());
            send_live_checkpoints(&sink, &attachment.live_checkpoints).await?;
            send_active_runtime_snapshots(state, session_id, &sink).await?;
            let handle =
                forward_session_events(sink, session_id, attachment.events, attachment.live_events);
            state.register_client_forwarder(client_id, handle).await;
            Ok(())
        }
        Err(error) => {
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await?;
            state.cancel_session_namespace_attach(session_id).await;
            Ok(())
        }
    }
}

async fn handle_attach_session_recent(
    request_id: u64,
    client_id: ClientId,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    attached_session: &mut Option<SessionId>,
    session_id: SessionId,
    limit: usize,
) -> Result<(), ServerError> {
    let total_started_at = Instant::now();
    state
        .metrics
        .increment_counter("server.attach_recent.total");
    state
        .metrics
        .record_histogram("server.attach_recent.limit", usize_to_u64(limit));
    recover_abandoned_session_runtime_work_best_effort(state, session_id).await;
    let namespace_started_at = Instant::now();
    let client_namespace = state.client_session_namespace(client_id).await;
    if let Err(active_namespace) = state
        .try_activate_session_namespace(session_id, client_namespace)
        .await
    {
        state.metrics.record_histogram(
            "server.attach_recent.namespace_activation_duration_ms",
            elapsed_ms(namespace_started_at),
        );
        state.metrics.record_histogram(
            "server.attach_recent.total_duration_ms",
            elapsed_ms(total_started_at),
        );
        return send_incompatible_active_session_response(writer, request_id, &active_namespace)
            .await;
    }
    state.metrics.record_histogram(
        "server.attach_recent.namespace_activation_duration_ms",
        elapsed_ms(namespace_started_at),
    );
    let attach_started_at = Instant::now();
    match state
        .sessions
        .attach_session_recent(session_id, client_id, limit)
        .await
    {
        Ok(attachment) => {
            state.complete_session_namespace_attach(session_id).await;
            finish_attach_session_recent_success(
                AttachRecentSuccessContext {
                    request_id,
                    writer,
                    client_id,
                    attached_session,
                },
                state,
                session_id,
                attachment,
                AttachRecentTimings {
                    total_started_at,
                    attach_started_at,
                },
            )
            .await
        }
        Err(error) => {
            state.metrics.record_histogram(
                "server.attach_recent.session_attach_duration_ms",
                elapsed_ms(attach_started_at),
            );
            state
                .metrics
                .increment_counter("server.attach_recent.error_total");
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await?;
            state.cancel_session_namespace_attach(session_id).await;
            state.metrics.record_histogram(
                "server.attach_recent.total_duration_ms",
                elapsed_ms(total_started_at),
            );
            Ok(())
        }
    }
}

async fn handle_attach_session_projection_window(
    request_id: u64,
    client_id: ClientId,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    attached_session: &mut Option<SessionId>,
    session_id: SessionId,
    request: bcode_session_models::ProjectionWindowRequest,
) -> Result<(), ServerError> {
    let total_started_at = Instant::now();
    state
        .metrics
        .increment_counter("server.attach_projection_window.total");
    recover_abandoned_session_runtime_work_best_effort(state, session_id).await;
    let namespace_started_at = Instant::now();
    let client_namespace = state.client_session_namespace(client_id).await;
    if let Err(active_namespace) = state
        .try_activate_session_namespace(session_id, client_namespace)
        .await
    {
        state.metrics.record_histogram(
            "server.attach_projection_window.namespace_activation_duration_ms",
            elapsed_ms(namespace_started_at),
        );
        state.metrics.record_histogram(
            "server.attach_projection_window.total_duration_ms",
            elapsed_ms(total_started_at),
        );
        return send_incompatible_active_session_response(writer, request_id, &active_namespace)
            .await;
    }
    state.metrics.record_histogram(
        "server.attach_projection_window.namespace_activation_duration_ms",
        elapsed_ms(namespace_started_at),
    );
    let attach_started_at = Instant::now();
    match state
        .sessions
        .attach_session_projection_window(session_id, client_id, request)
        .await
    {
        Ok(window_attachment) => {
            state.complete_session_namespace_attach(session_id).await;
            finish_attach_session_projection_window_success(
                AttachProjectionWindowSuccessContext {
                    request_id,
                    writer,
                    client_id,
                    attached_session,
                },
                state,
                session_id,
                window_attachment,
                AttachRecentTimings {
                    total_started_at,
                    attach_started_at,
                },
            )
            .await
        }
        Err(error) => {
            state.metrics.record_histogram(
                "server.attach_projection_window.session_attach_duration_ms",
                elapsed_ms(attach_started_at),
            );
            state
                .metrics
                .increment_counter("server.attach_projection_window.error_total");
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await?;
            state.cancel_session_namespace_attach(session_id).await;
            state.metrics.record_histogram(
                "server.attach_projection_window.total_duration_ms",
                elapsed_ms(total_started_at),
            );
            Ok(())
        }
    }
}

struct AttachProjectionWindowSuccessContext<'a> {
    request_id: u64,
    writer: &'a SharedWriter,
    client_id: ClientId,
    attached_session: &'a mut Option<SessionId>,
}

async fn finish_attach_session_projection_window_success(
    context: AttachProjectionWindowSuccessContext<'_>,
    state: &Arc<ServerState>,
    session_id: SessionId,
    window_attachment: bcode_session::SessionProjectionWindowAttachment,
    timings: AttachRecentTimings,
) -> Result<(), ServerError> {
    let projection_window = window_attachment.projection_window;
    let attachment = window_attachment.attachment;
    state.metrics.record_histogram(
        "server.attach_projection_window.session_attach_duration_ms",
        elapsed_ms(timings.attach_started_at),
    );
    state.metrics.record_histogram(
        "server.attach_projection_window.history_event_count",
        usize_to_u64(attachment.history.len()),
    );
    state.metrics.record_histogram(
        "server.attach_projection_window.input_history_entry_count",
        usize_to_u64(attachment.input_history.len()),
    );
    state.metrics.record_histogram(
        "server.attach_projection_window.projection_item_count",
        usize_to_u64(projection_window.transcript_items.len()),
    );
    let restore_started_at = Instant::now();
    restore_active_skills_from_history(&attachment.history, state, session_id).await;
    state.metrics.record_histogram(
        "server.attach_projection_window.restore_active_skills_duration_ms",
        elapsed_ms(restore_started_at),
    );
    *context.attached_session = Some(session_id);
    state
        .attach_client_session(context.client_id, session_id)
        .await;
    let compact_started_at = Instant::now();
    let compacted_history = compact_attach_history(attachment.history);
    state.metrics.record_histogram(
        "server.attach_projection_window.compact_history_duration_ms",
        elapsed_ms(compact_started_at),
    );
    state.metrics.record_histogram(
        "server.attach_projection_window.compacted_history_event_count",
        usize_to_u64(compacted_history.len()),
    );
    let draft_started_at = Instant::now();
    let draft = state.sessions.session_composer_draft(session_id).await?;
    state.metrics.record_histogram(
        "server.attach_projection_window.load_draft_duration_ms",
        elapsed_ms(draft_started_at),
    );
    let runtime_selection_started_at = Instant::now();
    let runtime_selection = session_runtime_selection_payload(state, session_id).await;
    state.metrics.record_histogram(
        "server.attach_projection_window.runtime_selection_duration_ms",
        elapsed_ms(runtime_selection_started_at),
    );
    let response = Response::Ok(ResponsePayload::Attached {
        session_id,
        session: attachment.session,
        history: compacted_history,
        input_history: attachment.input_history,
        import_warnings: Vec::new(),
        draft,
        runtime_selection,
        projection_window: Some(projection_window),
    });
    let send_started_at = Instant::now();
    send_response(context.writer, context.request_id, response).await?;
    state.metrics.record_histogram(
        "server.attach_projection_window.response_send_duration_ms",
        elapsed_ms(send_started_at),
    );
    state.metrics.record_histogram(
        "server.attach_projection_window.total_duration_ms",
        elapsed_ms(timings.total_started_at),
    );
    let sink = ClientEventSink::new(
        context.client_id,
        context.writer.clone(),
        state.metrics.clone(),
    );
    send_live_checkpoints(&sink, &attachment.live_checkpoints).await?;
    send_active_runtime_snapshots(state, session_id, &sink).await?;
    let handle =
        forward_session_events(sink, session_id, attachment.events, attachment.live_events);
    state
        .register_client_forwarder(context.client_id, handle)
        .await;
    Ok(())
}

