async fn handle_set_session_agent(
    request_id: u64,
    state: &ServerState,
    writer: &SharedWriter,
    session_id: SessionId,
    agent_id: String,
) -> Result<(), ServerError> {
    let Some(resolved_agent_id) = resolve_agent_id(state, &agent_id).await else {
        return send_response(
            writer,
            request_id,
            Response::Err(ErrorResponse::new(
                "unknown_agent",
                format!("unknown agent profile: {agent_id}"),
            )),
        )
        .await;
    };
    match state
        .sessions
        .set_current_agent(session_id, resolved_agent_id.clone())
        .await
    {
        Ok(()) => {
            state
                .session_agent_selections
                .lock()
                .await
                .insert(session_id, resolved_agent_id);
            send_response(
                writer,
                request_id,
                Response::Ok(ResponsePayload::SessionAgentSet),
            )
            .await
        }
        Err(error) => {
            send_response(
                writer,
                request_id,
                Response::Err(session_error_response(&error)),
            )
            .await
        }
    }
}

async fn close_session_turn(
    state: &ServerState,
    session_id: SessionId,
) -> Option<RuntimeCurrentTurn> {
    let current_turn = state.session_current_turn(session_id).await?;
    current_turn.cancel_state.close();
    Some(current_turn)
}

fn dispatch_provider_turn_cleanup(
    plugins: bcode_plugin::PluginRuntimeHost,
    metrics: MetricsRegistry,
    provider_plugin_id: String,
    interface_id: &'static str,
    request: CancelTurnRequest,
    scope: PluginInvocationScope,
) {
    tokio::spawn(async move {
        let started_at = Instant::now();
        let result = plugins
            .invoke_service_json_scoped::<_, bcode_model::AckResponse>(
                &provider_plugin_id,
                interface_id,
                OP_CANCEL_TURN,
                &request,
                scope,
            )
            .await;
        let outcome = if result.is_ok() {
            "completed"
        } else {
            "failed"
        };
        let mut labels = MetricLabels::new();
        labels.insert("cleanup_kind".to_owned(), "provider_turn".to_owned());
        labels.insert("outcome".to_owned(), outcome.to_owned());
        metrics.add_counter_with_labels("provider.cleanup_total", 1, labels.clone());
        metrics.record_histogram_with_labels(
            "provider.cleanup_duration_ms",
            elapsed_ms(started_at),
            labels,
        );
        match result {
            Ok(_) => tracing::debug!(
                target: "bcode_server::cleanup",
                plugin_id = %provider_plugin_id,
                provider_turn_id = %request.provider_turn_id,
                "detached provider cleanup completed"
            ),
            Err(error) => tracing::warn!(
                target: "bcode_server::cleanup",
                plugin_id = %provider_plugin_id,
                provider_turn_id = %request.provider_turn_id,
                %error,
                "detached provider cleanup failed"
            ),
        }
    });
}

async fn finish_session_turn_cancellation(
    state: &ServerState,
    session_id: SessionId,
    current_turn: RuntimeCurrentTurn,
    requested_by: Option<ClientId>,
) {
    current_turn.cancel_state.wait_for_commit_boundary().await;
    if current_turn.kind == RuntimeOperationKind::ModelTurn
        && let Some(model) = current_turn.model.as_ref()
    {
        let provider_plugin_id = Some(model.identity.provider_plugin_id.clone()).or_else(|| {
            state
                .plugins
                .registry()
                .service_registry()
                .unique_provider(MODEL_PROVIDER_INTERFACE_ID)
                .ok()
                .map(ToString::to_string)
        });
        if let Some(provider_plugin_id) = provider_plugin_id
            && let Some(interface_id) =
                model_provider_interface_for_plugin(state, &provider_plugin_id)
        {
            dispatch_provider_turn_cleanup(
                state.plugins.clone(),
                state.metrics.clone(),
                provider_plugin_id,
                interface_id,
                CancelTurnRequest {
                    provider_turn_id: model.provider_turn_id.clone(),
                },
                current_turn.plugin_scope_for_provider(session_id),
            );
        }
    }
    let turn_id = current_turn.turn_id;
    if current_turn.kind == RuntimeOperationKind::ModelTurn {
        append_model_turn_cancel_requested_event(state, session_id, turn_id.clone(), requested_by)
            .await;
        cancel_registered_runtime_work(
            state,
            session_id,
            WorkId::new(format!("model_{turn_id}")),
            requested_by,
        )
        .await;
    }
}

async fn handle_cancel_session_turn(
    request_id: u64,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    session_id: SessionId,
    client_id: ClientId,
    clear_queue: bool,
) -> Result<(), ServerError> {
    let cancelled =
        enqueue_cancel_turn_command(state, session_id, clear_queue, Some(client_id)).await?;
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::TurnCancellationRequested { cancelled }),
    )
    .await
}

fn record_workflow_authoring_duration(
    metrics: &MetricsRegistry,
    metric: &'static str,
    started_at: Instant,
    outcome: &'static str,
) {
    metrics.record_histogram_with_exact_labels(
        metric,
        elapsed_ms(started_at),
        BTreeMap::from([("outcome".to_string(), outcome.to_string())]),
    );
}

fn record_workflow_authoring_conflict(metrics: &MetricsRegistry, operation: &'static str) {
    metrics.add_counter_with_exact_labels(
        "workflow.authoring.conflicts_total",
        1,
        BTreeMap::from([("operation".to_string(), operation.to_string())]),
    );
}

async fn run_workflow_computation<T, F>(
    state: &ServerState,
    control: bcode_ipc::WorkflowComputationControl,
    fallback_operation_id: String,
    compute: F,
) -> Result<T, ServerError>
where
    T: Send + 'static,
    F: FnOnce() -> T + Send + 'static,
{
    let operation_id = if control.operation_id.is_empty() {
        fallback_operation_id
    } else {
        control.operation_id
    };
    if operation_id.len() > 512
        || operation_id.is_empty()
        || control.timeout_ms == 0
        || control.timeout_ms > bcode_ipc::MAX_WORKFLOW_COMPUTATION_TIMEOUT_MS
    {
        return Err(ServerError::WorkflowComputationControlInvalid(
            "operation identity or timeout is outside supported bounds".to_string(),
        ));
    }
    let cancellation = Arc::new(WorkflowComputationCancellation::new());
    {
        let mut computations = state
            .workflow_computations
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if computations.contains_key(&operation_id) {
            return Err(ServerError::WorkflowComputationControlInvalid(format!(
                "workflow computation operation is already active: {operation_id}"
            )));
        }
        computations.insert(operation_id.clone(), Arc::clone(&cancellation));
    }
    let mut task = tokio::task::spawn_blocking(compute);
    let outcome = tokio::select! {
        result = &mut task => result.map_err(ServerError::BlockingTask),
        () = cancellation.notify.notified() => {
            Err(ServerError::WorkflowComputationCancelled(operation_id.clone()))
        }
        () = tokio::time::sleep(Duration::from_millis(control.timeout_ms)) => {
            cancellation.cancel();
            Err(ServerError::WorkflowComputationTimedOut(operation_id.clone()))
        }
    };
    state
        .workflow_computations
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .remove(&operation_id);
    outcome
}

fn cancel_workflow_computation(state: &ServerState, operation_id: &str) -> bool {
    let cancellation = state
        .workflow_computations
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .get(operation_id)
        .cloned();
    cancellation.is_some_and(|cancellation| {
        cancellation.cancel();
        true
    })
}

async fn handle_create_authored_workflow(
    request_id: u64,
    client_id: ClientId,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    request: bcode_ipc::CreateAuthoredWorkflowRequest,
) -> Result<(), ServerError> {
    request.document.validate()?;
    let workflow_id = request.document.workflow_id.clone();
    let producer = request.document.producer.clone();
    state.authorize_local_workflow_application_operation(
        client_id,
        LocalWorkflowApplicationOperationRequest {
            operation: bcode_workflow::WorkflowApplicationOperation::CreateWorkflow,
            workflow_id: workflow_id.clone(),
            draft_id: None,
            revision: None,
            preset_id: None,
            producer: Some(producer.clone()),
            requirements: request.document.requirements.clone(),
            effects: bcode_workflow::WorkflowEffectSummary::default(),
            activates: false,
            executes: false,
        },
    )?;
    let now = current_time_ms();
    let workflow = bcode_workflow_store::AuthoredWorkflow {
        workflow_id: workflow_id.clone(),
        title: request.document.metadata.title.clone(),
        description: request.document.metadata.description.clone(),
        archived: false,
        active_revision: None,
        created_at_ms: now,
        updated_at_ms: now,
    };
    let draft = bcode_workflow_store::WorkflowDraft {
        workflow_id,
        draft_id: request.draft_id,
        base_revision: None,
        generation: 1,
        checksum_sha256: request.document.source_digest_sha256()?,
        document: request.document,
        producer,
        created_at_ms: now,
        updated_at_ms: now,
    };
    state
        .workflow_store
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .create_authored_workflow_with_initial_draft(&workflow, &draft)?;
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::AuthoredWorkflowCreated {
            workflow: authored_workflow_snapshot(workflow),
            draft: Box::new(workflow_draft_snapshot(draft)),
        }),
    )
    .await
}

async fn handle_update_workflow_draft(
    request_id: u64,
    client_id: ClientId,
    state: &Arc<ServerState>,
    writer: &SharedWriter,
    request: bcode_ipc::UpdateWorkflowDraftRequest,
) -> Result<(), ServerError> {
    request.document.validate()?;
    if request.document.workflow_id != request.workflow_id {
        return Err(ServerError::WorkflowDefinitionUnsupported(
            "draft document workflow identity does not match the request".to_string(),
        ));
    }
    state.authorize_local_workflow_application_operation(
        client_id,
        LocalWorkflowApplicationOperationRequest {
            operation: bcode_workflow::WorkflowApplicationOperation::UpdateDraft,
            workflow_id: request.workflow_id.clone(),
            draft_id: Some(request.draft_id.clone()),
            revision: None,
            preset_id: None,
            producer: Some(request.producer.clone()),
            requirements: request.document.requirements.clone(),
            effects: bcode_workflow::WorkflowEffectSummary::default(),
            activates: false,
            executes: false,
        },
    )?;
    let update = state
        .workflow_store
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .update_workflow_draft(
            &request.workflow_id,
            &request.draft_id,
            request.expected_generation,
            &request.document,
            &request.producer,
            current_time_ms(),
        );
    let result = match update {
        Ok(draft) => {
            bcode_ipc::WorkflowDraftUpdateResult::Updated(Box::new(workflow_draft_snapshot(draft)))
        }
        Err(WorkflowStoreError::AuthoringConflict {
            entity_id,
            expected,
            current,
        }) => {
            record_workflow_authoring_conflict(&state.metrics, "update_draft");
            bcode_ipc::WorkflowDraftUpdateResult::Conflict(bcode_ipc::WorkflowAuthoringConflict {
                entity_id,
                expected_generation: expected,
                current_generation: current,
            })
        }
        Err(error) => return Err(error.into()),
    };
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::WorkflowDraftUpdateResult { result }),
    )
    .await
}

fn authoring_conflict_result(
    error: WorkflowStoreError,
) -> Result<bcode_ipc::WorkflowAuthoringConflict, WorkflowStoreError> {
    match error {
        WorkflowStoreError::AuthoringConflict {
            entity_id,
            expected,
            current,
        } => Ok(bcode_ipc::WorkflowAuthoringConflict {
            entity_id,
            expected_generation: expected,
            current_generation: current,
        }),
        error => Err(error),
    }
}

