async fn start_workflow_run(
    state: &Arc<ServerState>,
    request: bcode_ipc::WorkflowRunStartRequest,
    authored_provenance: Option<bcode_workflow_store::AuthoredWorkflowRunProvenance>,
) -> Result<bcode_ipc::WorkflowRunStartResponse, ServerError> {
    let stored_definition = state
        .workflow_store
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .definition(&request.definition_id, request.definition_version)?
        .ok_or_else(|| {
            ServerError::WorkflowCapabilityUnavailable(format!(
                "workflow definition not found: {} v{}",
                request.definition_id, request.definition_version
            ))
        })?;
    let definition: bcode_workflow::WorkflowDefinition =
        serde_json::from_str(&stored_definition.definition_json)?;
    validate_workflow_definition_for_production(state, &definition)?;
    let parent_session = state
        .sessions
        .session_summary(request.parent_session_id)
        .await?;
    let run_id = request
        .run_id
        .clone()
        .unwrap_or_else(|| uuid::Uuid::new_v4().to_string());
    let created_at_ms = current_unix_millis();
    let workspace_snapshot = if request.workspace_snapshot.is_empty() {
        parent_session
            .working_directory
            .to_string_lossy()
            .into_owned()
    } else {
        request.workspace_snapshot
    };
    let new_run = bcode_workflow_store::NewWorkflowRun {
        run_id: run_id.clone(),
        definition_id: request.definition_id.clone(),
        definition_version: request.definition_version,
        workspace_snapshot,
        parent_session_id: Some(request.parent_session_id.to_string()),
        binding: request.binding,
        authored_provenance,
        input: request.input,
        created_at_ms,
        limits: request.limits,
    };
    let run = {
        let mut store = state
            .workflow_store
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let _created = store.create_run_idempotent(&new_run)?;
        store
            .run_summary(&run_id)?
            .expect("created or existing workflow run must be readable")
    };
    let runtime_work_id = register_workflow_runtime_work(
        state,
        parent_session.id,
        &run_id,
        format!(
            "workflow {} v{}",
            request.definition_id, request.definition_version
        ),
    )
    .await;
    drive_workflow_run(state, &run_id).await?;
    Ok(bcode_ipc::WorkflowRunStartResponse {
        run,
        runtime_work_id,
    })
}

async fn drive_workflow_run(state: &Arc<ServerState>, run_id: &str) -> Result<(), ServerError> {
    let started_at = std::time::Instant::now();
    let store_path = state
        .workflow_store
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .path()
        .to_path_buf();
    loop {
        let iteration_started_at = std::time::Instant::now();
        let settled = bcode_workflow_store::WorkflowStore::open_at_path(&store_path)?
            .settle_pending_control_nodes(run_id, 1_000, current_unix_millis())?;
        let owner = WorkflowActivationOwner { state };
        let dispatched = bcode_workflow_store::WorkflowStore::open_at_path(&store_path)?
            .dispatch_pending_activations_for_run(&owner, run_id, 1_000, current_unix_millis())
            .await?;
        let observer = WorkflowTurnReceiptObserver { state };
        let reconciled = bcode_workflow_store::WorkflowStore::open_at_path(&store_path)?
            .reconcile_receipt_backed_attempts_for_run_async(
                &observer,
                run_id,
                1_000,
                current_unix_millis(),
            )
            .await?;
        if !reconciled.sibling_cancellations.is_empty() {
            propagate_fail_fast_sibling_cancellation(
                state,
                reconciled.sibling_cancellations.clone(),
            )
            .await?;
        }
        if !dispatched.unsupported.is_empty() {
            tracing::debug!(
                run_id,
                unsupported = ?dispatched.unsupported,
                "workflow run has pending activations without a production owner"
            );
        }
        state.metrics.record_histogram(
            "workflow.scheduler.iteration.duration_ms",
            u64::try_from(iteration_started_at.elapsed().as_millis()).unwrap_or(u64::MAX),
        );
        if settled.settled.is_empty()
            && dispatched.admitted.is_empty()
            && reconciled.succeeded.is_empty()
            && reconciled.failed.is_empty()
            && reconciled.paused.is_empty()
            && reconciled.cancelled.is_empty()
            && reconciled.repair_required.is_empty()
        {
            break;
        }
    }
    state.metrics.record_histogram(
        "workflow.scheduler.drive.duration_ms",
        u64::try_from(started_at.elapsed().as_millis()).unwrap_or(u64::MAX),
    );
    Ok(())
}

async fn drive_workflow_run_and_parents(
    state: &Arc<ServerState>,
    initial_run_id: &str,
) -> Result<(), ServerError> {
    let mut next = Some(initial_run_id.to_string());
    let mut visited = BTreeSet::new();
    while let Some(run_id) = next {
        if !visited.insert(run_id.clone()) {
            return Err(ServerError::WorkflowDefinitionUnsupported(
                "workflow parent link cycle detected while driving completion".to_string(),
            ));
        }
        drive_workflow_run(state, &run_id).await?;
        next = state
            .workflow_store
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .parent_run_link(&run_id)?
            .map(|link| link.parent_run_id);
    }
    Ok(())
}

