async fn workflow_run_inspection(
    state: &ServerState,
    run_id: &str,
    limit: usize,
) -> Result<bcode_ipc::WorkflowRunInspection, ServerError> {
    let (
        run,
        definition,
        activations,
        waits,
        mutation_approvals,
        attempts,
        events,
        decisions,
        grants,
        resource_leases,
        outputs,
        child_run_links,
        repeat_outcomes,
    ) = {
        let store = state
            .workflow_store
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let run = store.run_summary(run_id)?.ok_or_else(|| {
            WorkflowStoreError::InvalidData(format!("workflow run not found: {run_id}"))
        })?;
        let definition = store
            .definition(&run.definition_id, run.definition_version)?
            .ok_or_else(|| {
                WorkflowStoreError::InvalidData(format!(
                    "workflow definition not found: {} v{}",
                    run.definition_id, run.definition_version
                ))
            })?;
        (
            run,
            definition,
            store.activations_for_run(run_id, limit)?,
            store.waiting_activations(run_id, limit)?,
            store.pending_mutation_approvals(run_id, limit)?,
            store.attempt_history(run_id, None, limit)?,
            store.event_history(run_id, None, limit)?,
            store.decisions_for_run(run_id, limit)?,
            store.grants_for_run(run_id, limit)?,
            store.resource_leases_for_run(run_id, limit)?,
            store.output_summaries(run_id, limit)?,
            store.child_run_links(run_id, limit)?,
            store.repeat_outcomes(run_id, limit)?,
        )
    };
    let child_sessions = state
        .sessions
        .all_session_summaries()
        .await
        .into_iter()
        .filter(|session| {
            session
                .execution
                .as_ref()
                .is_some_and(|execution| execution.provenance.run_id == run_id)
        })
        .take(limit)
        .collect();
    Ok(bcode_ipc::WorkflowRunInspection {
        run,
        definition,
        activations,
        waits,
        mutation_approvals,
        attempts,
        events,
        decisions,
        grants,
        resource_leases,
        outputs,
        child_run_links,
        repeat_outcomes,
        child_sessions,
    })
}

