async fn resolve_pending_permission(
    state: &ServerState,
    permission: PendingPermission,
    approved: bool,
    remember: bool,
) {
    if remember && let Some(key) = permission.skill_decision_key.clone() {
        remember_skill_tool_decision(
            key,
            if approved {
                SkillToolDecision::Allow
            } else {
                SkillToolDecision::Deny
            },
        );
    }
    *permission.decision.lock().await = Some(approved);
    permission.notify.notify_waiters();
    append_permission_resolved_event(
        state,
        permission.summary.session_id,
        permission.summary.permission_id,
        approved,
    )
    .await;
}

async fn take_pending_permission_for_individual(
    state: &ServerState,
    permission_id: &str,
) -> Option<PendingPermission> {
    let candidate = state
        .pending_permissions
        .lock()
        .await
        .get(permission_id)
        .cloned()?;
    let Some(correlation) = candidate.summary.batch.as_ref() else {
        return state.pending_permissions.lock().await.remove(permission_id);
    };
    let batch = state
        .pending_permission_batches
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .get(&correlation.batch_id)
        .cloned();
    let Some(batch) = batch else {
        state.pending_permissions.lock().await.remove(permission_id);
        return None;
    };
    let batch_decision = batch.decision.lock().await;
    if batch_decision.is_some() {
        return None;
    }
    let permission = state.pending_permissions.lock().await.remove(permission_id);
    drop(batch_decision);
    permission
}

async fn handle_resolve_permission(
    request_id: u64,
    state: &ServerState,
    writer: &SharedWriter,
    permission_id: &str,
    approved: bool,
    remember: bool,
) -> Result<(), ServerError> {
    let Some(permission) = take_pending_permission_for_individual(state, permission_id).await
    else {
        return send_response(
            writer,
            request_id,
            Response::Ok(ResponsePayload::PermissionResolved { resolved: false }),
        )
        .await;
    };
    resolve_pending_permission(state, permission, approved, remember).await;
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::PermissionResolved { resolved: true }),
    )
    .await
}

async fn resolve_permission_batch(state: &ServerState, batch_id: &str, approved: bool) -> usize {
    let Some(batch) = state
        .pending_permission_batches
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .get(batch_id)
        .cloned()
    else {
        return 0;
    };
    let mut batch_decision = batch.decision.lock().await;
    if batch_decision.is_some() {
        return 0;
    }
    *batch_decision = Some(approved);
    drop(batch_decision);

    let permissions = {
        let permission_ids = {
            let pending = state.pending_permissions.lock().await;
            pending
                .iter()
                .filter(|(_, permission)| {
                    permission
                        .summary
                        .batch
                        .as_ref()
                        .is_some_and(|batch| batch.batch_id == batch_id)
                })
                .map(|(permission_id, _)| permission_id.clone())
                .collect::<Vec<_>>()
        };
        let mut pending = state.pending_permissions.lock().await;
        let mut permissions = Vec::with_capacity(permission_ids.len());
        for permission_id in permission_ids {
            if let Some(permission) = pending.remove(&permission_id) {
                permissions.push(permission);
            }
        }
        permissions
    };
    let resolved = permissions.len();
    for permission in permissions {
        resolve_pending_permission(state, permission, approved, false).await;
    }
    resolved
}

async fn handle_resolve_permission_batch(
    request_id: u64,
    state: &ServerState,
    writer: &SharedWriter,
    batch_id: &str,
    approved: bool,
) -> Result<(), ServerError> {
    let resolved = resolve_permission_batch(state, batch_id, approved).await;
    send_response(
        writer,
        request_id,
        Response::Ok(ResponsePayload::PermissionBatchResolved { resolved }),
    )
    .await
}

const MODEL_POLL_INTERVAL: Duration = Duration::from_millis(100);
const MODEL_STREAM_FLUSH_INTERVAL: Duration = Duration::from_millis(16);
const TOOL_ARGUMENTS_DECODE_FAILED_CODE: &str = "tool_arguments_decode_failed";
const MODEL_NO_PROGRESS_TIMEOUT_CODE: &str = "model_no_progress_timeout";
const MALFORMED_TOOL_ARGUMENTS_RETRY_INSTRUCTION: &str = "The previous model turn emitted malformed JSON for a tool call, so the tool did not run. Reissue the intended tool call with valid JSON arguments. Do not explain unless the user explicitly asked for an explanation.";
const MAX_TOKENS_CONTINUATION_INSTRUCTION: &str = "Continue exactly where the previous response stopped. Do not repeat completed content. Finish the pending task, including any required tool calls.";
const MAX_TOKENS_CONTINUATION_LIMIT: u32 = 8;

#[derive(Debug, Clone, Default)]
struct ModelPollOutcome {
    stop_reason: Option<bcode_model::StopReason>,
    completion: Option<ModelTurnCompletion>,
    assistant_output: Option<String>,
    provider_error: Option<bcode_model::ProviderError>,
    pending_managed_compaction: Option<PendingManagedCompaction>,
    pending_provider_response_id: Option<String>,
    pending_tool_calls: Vec<bcode_model::ToolCall>,
    reasoning_activities: BTreeMap<String, ReasoningActivityAccumulator>,
    tool_output_positions: BTreeMap<String, (String, bcode_session_models::TurnOutputPosition)>,
    reasoning_text_streams: BTreeMap<(String, String), (u64, usize)>,
    saw_reasoning_evidence: bool,
}

#[derive(Debug, Clone)]
struct ReasoningActivityAccumulator {
    activity_id: String,
    order: u32,
    output_position: Option<bcode_session_models::TurnOutputPosition>,
    status: Option<bcode_session_models::ReasoningActivityStatus>,
    parts: BTreeMap<String, bcode_session_models::ReasoningPart>,
    completed_parts: BTreeSet<String>,
    opaque: bool,
}

impl ReasoningActivityAccumulator {
    const fn new(activity_id: String, order: u32) -> Self {
        Self {
            activity_id,
            order,
            output_position: None,
            status: None,
            parts: BTreeMap::new(),
            completed_parts: BTreeSet::new(),
            opaque: false,
        }
    }

    fn apply(&mut self, event: &bcode_session_models::ReasoningActivityEvent) {
        use bcode_session_models::ReasoningActivityEvent;
        match event {
            ReasoningActivityEvent::Started { .. } => {}
            ReasoningActivityEvent::PartDelta {
                part_id,
                kind,
                role,
                part_order,
                text,
                ..
            } => {
                if self.completed_parts.contains(part_id) {
                    return;
                }
                let part = self.parts.entry(part_id.clone()).or_insert_with(|| {
                    bcode_session_models::ReasoningPart {
                        part_id: part_id.clone(),
                        kind: *kind,
                        role: *role,
                        order: *part_order,
                        text: String::new(),
                    }
                });
                part.kind = *kind;
                part.role = *role;
                part.order = *part_order;
                part.text.push_str(text);
            }
            ReasoningActivityEvent::PartCompleted {
                part_id,
                kind,
                role,
                part_order,
                text,
                ..
            } => {
                self.completed_parts.insert(part_id.clone());
                self.parts.insert(
                    part_id.clone(),
                    bcode_session_models::ReasoningPart {
                        part_id: part_id.clone(),
                        kind: *kind,
                        role: *role,
                        order: *part_order,
                        text: text.clone(),
                    },
                );
            }
            ReasoningActivityEvent::OpaqueObserved { .. } => self.opaque = true,
            ReasoningActivityEvent::Finished { status, .. } => self.status = Some(*status),
        }
    }

    fn finish(
        self,
        fallback_status: bcode_session_models::ReasoningActivityStatus,
    ) -> bcode_session_models::ReasoningActivity {
        let status = if fallback_status == bcode_session_models::ReasoningActivityStatus::Completed
        {
            self.status.unwrap_or(fallback_status)
        } else {
            fallback_status
        };
        let mut parts = self
            .parts
            .into_values()
            .filter(|part| {
                status == bcode_session_models::ReasoningActivityStatus::Completed
                    || self.completed_parts.contains(&part.part_id)
            })
            .collect::<Vec<_>>();
        parts.sort_by_key(|part| (part.order, part.kind, part.part_id.clone()));
        bcode_session_models::ReasoningActivity {
            activity_id: self.activity_id,
            order: self.order,
            status,
            parts,
            opaque: self.opaque,
        }
    }
}

