#[derive(Debug)]
struct ModelStreamAccumulator {
    session_id: SessionId,
    turn_id: String,
    segment_id: String,
    segment_order: u32,
    output_position: Option<bcode_session_models::TurnOutputPosition>,
    assistant_text: String,
    pending_text: String,
    pending_text_offset: usize,
    next_text_revision: u64,
    last_flush: Instant,
    cancel_state: Arc<TurnCancelState>,
}

impl ModelStreamAccumulator {
    fn new(
        session_id: SessionId,
        turn_id: &str,
        segment_order: u32,
        cancel_state: Arc<TurnCancelState>,
    ) -> Self {
        Self {
            session_id,
            turn_id: turn_id.to_owned(),
            segment_id: format!("segment-{segment_order}"),
            segment_order,
            output_position: None,
            assistant_text: String::new(),
            pending_text: String::new(),
            pending_text_offset: 0,
            next_text_revision: 1,
            last_flush: Instant::now(),
            cancel_state,
        }
    }

    fn push_text(&mut self, text: &str) {
        if self.cancel_state.is_cancelled() {
            return;
        }
        self.assistant_text.push_str(text);
        self.pending_text.push_str(text);
    }

    fn should_flush(&self) -> bool {
        !self.pending_text.is_empty() && self.last_flush.elapsed() >= MODEL_STREAM_FLUSH_INTERVAL
    }

    async fn flush_if_ready(&mut self, state: &ServerState) {
        if self.should_flush() {
            self.flush(state).await;
        }
    }

    async fn flush(&mut self, state: &ServerState) {
        if self.cancel_state.is_cancelled() {
            self.assistant_text.clear();
            self.pending_text.clear();
            return;
        }
        let text = std::mem::take(&mut self.pending_text);
        if !text.is_empty() {
            let text_bytes = text.len();
            let revision = self.next_text_revision;
            let _ = state
                .sessions
                .publish_live_event(
                    self.session_id,
                    SessionLiveEventKind::AssistantTextStreamUpdated {
                        output_position: self.output_position,
                        turn_id: self.turn_id.clone(),
                        segment_id: self.segment_id.clone(),
                        segment_order: self.segment_order,
                        update: bcode_session_models::TextStreamUpdate {
                            generation: 0,
                            first_revision: revision,
                            revision,
                            operation: bcode_session_models::TextStreamOperation::Append {
                                expected_offset: self.pending_text_offset,
                                text,
                            },
                        },
                    },
                )
                .await;
            self.pending_text_offset = self.pending_text_offset.saturating_add(text_bytes);
            self.next_text_revision = revision.saturating_add(1);
        }
        self.last_flush = Instant::now();
    }

    fn take_assistant_segment(&mut self) -> Option<AssistantSegmentOutput> {
        let text = std::mem::take(&mut self.assistant_text);
        (!text.is_empty()).then(|| AssistantSegmentOutput {
            segment_id: self.segment_id.clone(),
            segment_order: self.segment_order,
            output_position: self.output_position,
            text,
        })
    }

    const fn output_position(&self) -> Option<bcode_session_models::TurnOutputPosition> {
        self.output_position
    }

    const fn set_output_position(
        &mut self,
        position: Option<bcode_session_models::TurnOutputPosition>,
    ) {
        self.output_position = position;
    }

    fn advance_segment(&mut self, segment_order: u32) {
        self.segment_order = segment_order;
        self.segment_id = format!("segment-{segment_order}");
        self.output_position = None;
        self.pending_text_offset = 0;
        self.next_text_revision = 1;
    }

    fn finish(self) -> Option<AssistantSegmentOutput> {
        (!self.assistant_text.is_empty()).then_some(AssistantSegmentOutput {
            segment_id: self.segment_id,
            segment_order: self.segment_order,
            output_position: self.output_position,
            text: self.assistant_text,
        })
    }
}

impl ModelStreamProgress {
    const MAX_TOOL_REQUEST_DRAFT_PREVIEW_BYTES: usize = 128 * 1024;

    fn start_tool_call(
        &mut self,
        call_id: String,
        name: String,
        producer_plugin_id: Option<String>,
    ) {
        self.start_tool_call_at(None, call_id, name, producer_plugin_id);
    }

    fn start_tool_call_at(
        &mut self,
        output_position: Option<bcode_session_models::TurnOutputPosition>,
        call_id: String,
        name: String,
        producer_plugin_id: Option<String>,
    ) {
        self.start_tool_call_with_presentation(
            output_position,
            call_id,
            name,
            ToolRequestDraftPresentation {
                producer_plugin_id,
                schema: "bcode.tool.request-draft".to_owned(),
                schema_version: 0,
                placement: bcode_session_models::ToolContributionPlacement::Request,
            },
        );
    }

    fn start_tool_call_with_presentation(
        &mut self,
        output_position: Option<bcode_session_models::TurnOutputPosition>,
        call_id: String,
        name: String,
        presentation: ToolRequestDraftPresentation,
    ) {
        let ToolRequestDraftPresentation {
            producer_plugin_id,
            schema,
            schema_version,
            placement,
        } = presentation;
        let generation = self
            .generations
            .entry(call_id.clone())
            .and_modify(|generation| *generation = generation.saturating_add(1))
            .or_insert(1);
        self.active_tool_calls.insert(
            call_id.clone(),
            ToolArgumentStreamProgress {
                output_position,
                call_id,
                name,
                producer_plugin_id,
                schema,
                schema_version,
                placement,
                generation: *generation,
                revision: 0,
                argument_bytes: 0,
                retained_preview: String::new(),
                preview_start_offset: 0,
                pending_text: String::new(),
                pending_offset: 0,
                pending_checkpoint: false,
                truncated: false,
            },
        );
    }

    fn record_completed_tool_call(&mut self, call: &bcode_model::ToolCall) {
        if !self.active_tool_calls.contains_key(&call.id) {
            self.start_tool_call(call.id.clone(), call.name.clone(), None);
        }
        if let Some(active) = self.active_tool_calls.get_mut(&call.id) {
            active.argument_bytes = serialized_tool_argument_len(&call.arguments);
        }
    }

    fn finish_tool_call(&mut self, call_id: &str) {
        self.active_tool_calls.remove(call_id);
    }

    fn record_tool_call_delta(&mut self, call_id: &str, delta: &str) {
        let Some(active) = self.active_tool_calls.get_mut(call_id) else {
            return;
        };
        active.argument_bytes = active.argument_bytes.saturating_add(delta.len());
        active.retained_preview.push_str(delta);
        if active.retained_preview.len() > Self::MAX_TOOL_REQUEST_DRAFT_PREVIEW_BYTES {
            let overflow = active
                .retained_preview
                .len()
                .saturating_sub(Self::MAX_TOOL_REQUEST_DRAFT_PREVIEW_BYTES);
            let split = active
                .retained_preview
                .char_indices()
                .map(|(index, _)| index)
                .find(|index| *index >= overflow)
                .unwrap_or(active.retained_preview.len());
            active.retained_preview.drain(..split);
            active.preview_start_offset = active.preview_start_offset.saturating_add(split);
            active.pending_checkpoint = true;
            active.truncated = true;
        } else if !active.pending_checkpoint {
            if active.pending_text.is_empty() {
                active.pending_offset = active.argument_bytes.saturating_sub(delta.len());
            }
            active.pending_text.push_str(delta);
        }
    }

    fn take_tool_request_draft_event(
        &mut self,
        turn_id: &str,
        call_id: &str,
    ) -> Option<bcode_session_models::ToolRequestDraftEvent> {
        let active = self.active_tool_calls.get_mut(call_id)?;
        if !active.pending_checkpoint && active.pending_text.is_empty() {
            return None;
        }
        active.revision = active.revision.saturating_add(1);
        let operation = if active.pending_checkpoint {
            active.pending_checkpoint = false;
            active.pending_text.clear();
            bcode_session_models::ToolRequestDraftOperation::Checkpoint {
                start_offset: active.preview_start_offset,
                text: active.retained_preview.clone(),
            }
        } else {
            let text = std::mem::take(&mut active.pending_text);
            if text.is_empty() {
                return None;
            }
            bcode_session_models::ToolRequestDraftOperation::Append {
                offset: active.pending_offset,
                text,
            }
        };
        Some(bcode_session_models::ToolRequestDraftEvent {
            output_position: active.output_position,
            turn_id: turn_id.to_owned(),
            tool_call_id: active.call_id.clone(),
            tool_name: active.name.clone(),
            producer_plugin_id: active.producer_plugin_id.clone(),
            schema: active.schema.clone(),
            schema_version: active.schema_version,
            placement: active.placement,
            generation: active.generation,
            revision: active.revision,
            operation,
            argument_bytes: active.argument_bytes,
            truncated: active.truncated,
        })
    }

    fn tool_request_draft_checkpoint(
        &self,
        turn_id: &str,
        call_id: &str,
    ) -> Option<bcode_session_models::ToolRequestDraftEvent> {
        let active = self.active_tool_calls.get(call_id)?;
        Some(bcode_session_models::ToolRequestDraftEvent {
            output_position: active.output_position,
            turn_id: turn_id.to_owned(),
            tool_call_id: active.call_id.clone(),
            tool_name: active.name.clone(),
            producer_plugin_id: active.producer_plugin_id.clone(),
            schema: active.schema.clone(),
            schema_version: active.schema_version,
            placement: active.placement,
            generation: active.generation,
            revision: active.revision,
            operation: bcode_session_models::ToolRequestDraftOperation::Checkpoint {
                start_offset: active.preview_start_offset,
                text: active.retained_preview.clone(),
            },
            argument_bytes: active.argument_bytes,
            truncated: active.truncated,
        })
    }

    fn tool_request_draft_checkpoints(
        &self,
        turn_id: &str,
    ) -> Vec<bcode_session_models::ToolRequestDraftEvent> {
        self.active_tool_calls
            .keys()
            .filter_map(|call_id| self.tool_request_draft_checkpoint(turn_id, call_id))
            .collect()
    }

    fn tool_progress_snapshot(&self) -> Option<ProviderToolCallProgress> {
        let active = self.active_tool_calls.values().next()?;
        Some(ProviderToolCallProgress {
            tool_call_id: active.call_id.clone(),
            tool_name: active.name.clone(),
            argument_bytes: active.argument_bytes,
        })
    }
}

fn serialized_tool_argument_len(arguments: &serde_json::Value) -> usize {
    serde_json::to_vec(arguments).map_or(0, |encoded| encoded.len())
}

