    #[tokio::test]
    async fn server_nested_service_router_aborts_blocked_provider_call_on_cancellation() {
        NON_RETURNING_SEARCH_STARTED.store(false, Ordering::SeqCst);
        NON_RETURNING_SEARCH_RELEASED.store(false, Ordering::SeqCst);
        NON_RETURNING_SEARCH_FINISHED.store(false, Ordering::SeqCst);
        let plugin = non_returning_search_provider_plugin();
        let plugins = bcode_plugin::PluginRuntimeHost::load_defaults_with_static_bundled(
            &bcode_plugin::PluginSelection {
                mode: bcode_plugin::PluginSelectionMode::Explicit,
                enabled: BTreeSet::from(["test.non-returning-search-provider".to_string()]),
                disabled: BTreeSet::new(),
            },
            &[plugin],
        )
        .expect("blocking search provider should load");
        let mut state = test_server_state(SessionManager::default());
        state.plugins = plugins;
        state.selected_provider_plugin_id = Some("test.non-returning-search-provider".to_string());
        let session_id = SessionId::new();
        let call = bcode_model::ToolCall {
            id: "search-call".to_string(),
            name: "web.search".to_string(),
            arguments: serde_json::Value::Null,
        };
        let cancel_state = Arc::new(TurnCancelState::default());
        let task_state = Arc::new(state);
        let task_cancel = Arc::clone(&cancel_state);
        let task = tokio::spawn(async move {
            ServerServiceRouter::new(task_state.as_ref(), session_id, &call, task_cancel.as_ref())
                .invoke(ToolInvocationServiceRequest {
                    invocation_id: "search-call".to_string(),
                    request_id: "search-request".to_string(),
                    route_id: Some(
                        "service-route:test.non-returning-search-provider:bcode.model-provider/v1"
                            .to_owned(),
                    ),
                    interface_id: MODEL_PROVIDER_INTERFACE_ID.to_string(),
                    operation: bcode_model::OP_NATIVE_WEB_SEARCH.to_string(),
                    payload: serde_json::json!({"query": "rust"}),
                })
                .await
        });

        tokio::time::timeout(Duration::from_secs(1), async {
            while !NON_RETURNING_SEARCH_STARTED.load(Ordering::SeqCst) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("nested provider service should start");
        cancel_state.close();
        let resolution = tokio::time::timeout(Duration::from_millis(100), task)
            .await
            .expect("nested service router must abort locally")
            .expect("router task should not panic");
        assert_eq!(resolution, ToolInvocationServiceResolution::Cancelled);
        assert!(!NON_RETURNING_SEARCH_FINISHED.load(Ordering::SeqCst));

        NON_RETURNING_SEARCH_RELEASED.store(true, Ordering::SeqCst);
        tokio::time::timeout(Duration::from_secs(1), async {
            while !NON_RETURNING_SEARCH_FINISHED.load(Ordering::SeqCst) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("provider worker should finish after release");
    }

    #[tokio::test]
    async fn cancel_acknowledgement_precedes_commit_bookkeeping() {
        let cancel_state = TurnCancelState::default();
        let commit = cancel_state.marker_commit.lock().await;
        cancel_state.close();
        let (response, completion) = oneshot::channel();
        let requested_by = acknowledge_cancel_command(
            CancelCommand {
                clear_queue: true,
                requested_by: None,
                response,
            },
            true,
        );

        assert_eq!(requested_by, None);
        assert!(completion.await.expect("cancellation acknowledgement"));
        let bookkeeping = cancel_state.wait_for_commit_boundary();
        assert!(
            tokio::time::timeout(Duration::from_millis(10), bookkeeping)
                .await
                .is_err(),
            "commit bookkeeping should still be independently blocked"
        );
        drop(commit);
    }

    #[tokio::test]
    async fn turn_local_closure_precedes_persistence_commit_barrier() {
        let cancel_state = Arc::new(TurnCancelState::default());
        let commit = cancel_state.marker_commit.lock().await;
        let cancelling = Arc::clone(&cancel_state);
        let cancel = tokio::spawn(async move {
            cancelling.cancel().await;
        });

        tokio::time::timeout(Duration::from_millis(100), cancel_state.cancelled())
            .await
            .expect("local cancellation token must close before commit coordination");
        assert!(!cancel.is_finished());

        drop(commit);
        tokio::time::timeout(Duration::from_millis(100), cancel)
            .await
            .expect("cancellation should finish after commit coordination")
            .expect("cancellation task should not panic");
    }

    #[tokio::test]
    async fn server_input_router_delivers_owned_input_and_wakes_on_cancellation() {
        let (sender, receiver) = mpsc::channel(ACTIVE_INVOCATION_INPUT_QUEUE_CAPACITY);
        let receiver = Mutex::new(receiver);
        let cancel_state = TurnCancelState::default();
        let router = ServerInputRouter::new("call-1", &receiver, &cancel_state);
        sender
            .try_send(ToolInvocationInput {
                invocation_id: "call-1".to_string(),
                input_id: "input-1".to_string(),
                producer_id: "bcode.shell".to_string(),
                schema: "bcode.shell.invocation-input".to_string(),
                schema_version: 1,
                payload: serde_json::json!({"type": "resize", "columns": 100, "rows": 30}),
            })
            .expect("send input");
        assert!(matches!(
            router.receive("call-1").await,
            ToolInvocationInputResolution::Received { input }
                if input.input_id == "input-1" && input.invocation_id == "call-1"
        ));
        assert!(matches!(
            router.receive("other").await,
            ToolInvocationInputResolution::Failed { code, .. }
                if code == "invocation_id_mismatch"
        ));

        let waiting = router.receive("call-1");
        tokio::pin!(waiting);
        tokio::select! {
            _ = &mut waiting => panic!("input wait completed before cancellation"),
            () = tokio::time::sleep(Duration::from_millis(10)) => {}
        }
        cancel_state.cancel().await;
        assert_eq!(waiting.await, ToolInvocationInputResolution::Cancelled);
        receiver.lock().await.close();
        assert!(matches!(
            sender.try_send(ToolInvocationInput {
                invocation_id: "call-1".to_string(),
                input_id: "late".to_string(),
                producer_id: "bcode.shell".to_string(),
                schema: "bcode.shell.invocation-input".to_string(),
                schema_version: 1,
                payload: serde_json::Value::Null,
            }),
            Err(mpsc::error::TrySendError::Closed(_))
        ));
    }
    fn test_artifact_scope(invocation_id: &str) -> InvocationScope {
        InvocationScope::new(
            TurnScope::without_events("test-artifact", TurnGeneration::new(1)),
            invocation_id.to_string(),
        )
    }

    #[tokio::test]
    async fn session_artifact_sink_writes_bounded_owned_artifacts_transactionally() {
        let root = tempfile::tempdir().expect("artifact sink root");
        let cancel_state = TurnCancelState::default();
        let sink =
            SessionArtifactSink::new(root.path().to_path_buf(), "artifact-call", &cancel_state);
        let request = ToolArtifactWriteRequest {
            invocation_id: "artifact-call".to_string(),
            artifact_id: "result".to_string(),
            content_type: "application/octet-stream".to_string(),
            bytes: b"artifact bytes".to_vec(),
            metadata: serde_json::json!({"kind": "test"}),
        };
        let resolution = sink
            .write(
                request.clone(),
                test_artifact_scope("artifact-call").artifact_commit_guard(),
            )
            .await;
        let ToolArtifactWriteResolution::Written {
            artifact_id,
            byte_len,
            reference,
        } = resolution
        else {
            panic!("expected artifact write, got {resolution:?}");
        };
        assert_eq!(artifact_id, "result");
        assert_eq!(byte_len, 14);
        let uri = reference["uri"].as_str().expect("artifact capability URI");
        assert!(uri.starts_with("bcode-artifact://invocation/"));
        assert!(!uri.contains(root.path().to_string_lossy().as_ref()));
        let artifact_directory = root
            .path()
            .join("invocation-artifacts")
            .read_dir()
            .expect("invocation artifact root")
            .next()
            .expect("invocation artifact directory")
            .expect("invocation artifact entry")
            .path();
        let path = artifact_directory
            .read_dir()
            .expect("artifact directory")
            .find_map(|entry| {
                let path = entry.ok()?.path();
                (path.extension().and_then(|extension| extension.to_str()) == Some("bin"))
                    .then_some(path)
            })
            .expect("persisted artifact");
        assert_eq!(std::fs::read(path).expect("artifact bytes"), request.bytes);
        assert!(
            !artifact_directory
                .read_dir()
                .expect("artifact directory")
                .any(|entry| entry
                    .expect("artifact directory entry")
                    .file_name()
                    .to_string_lossy()
                    .ends_with(".tmp"))
        );

        assert!(matches!(
            sink.write(request, test_artifact_scope("artifact-call").artifact_commit_guard()).await,
            ToolArtifactWriteResolution::Failed { code, .. } if code == "duplicate_artifact"
        ));
    }

    #[test]
    fn session_artifact_write_rolls_back_publication_when_cancellation_wins() {
        let root = tempfile::tempdir().expect("artifact sink root");
        let cancel_state = TurnCancelState::default();
        let request = ToolArtifactWriteRequest {
            invocation_id: "artifact-call".to_string(),
            artifact_id: "cancelled-result".to_string(),
            content_type: "application/octet-stream".to_string(),
            bytes: b"artifact bytes".to_vec(),
            metadata: serde_json::Value::Null,
        };

        let scope = test_artifact_scope("artifact-call");
        let result = write_session_invocation_artifact_with_publish_hook(
            root.path(),
            "artifact-call",
            &request,
            &cancel_state,
            scope.artifact_commit_guard(),
            || cancel_state.close(),
        );

        assert!(matches!(result, Err((code, _)) if code == "cancelled"));
        let invocation_directory = root.path().join("invocation-artifacts");
        let published_files = std::fs::read_dir(invocation_directory)
            .expect("invocation artifact root")
            .flat_map(|entry| {
                std::fs::read_dir(entry.expect("invocation directory").path())
                    .expect("artifact directory")
            })
            .filter_map(Result::ok)
            .collect::<Vec<_>>();
        assert!(
            published_files.is_empty(),
            "cancelled publication leaked files"
        );
    }

    #[tokio::test]
    async fn session_artifact_sink_enforces_identity_bound_and_cancellation() {
        let root = tempfile::tempdir().expect("artifact sink root");
        let active = TurnCancelState::default();
        let sink = SessionArtifactSink::new(root.path().to_path_buf(), "active", &active);
        assert!(matches!(
            sink.write(ToolArtifactWriteRequest {
                invocation_id: "other".to_string(),
                artifact_id: "wrong".to_string(),
                content_type: "application/octet-stream".to_string(),
                bytes: Vec::new(),
                metadata: serde_json::Value::Null,
            }, test_artifact_scope("active").artifact_commit_guard())
            .await,
            ToolArtifactWriteResolution::Failed { code, .. }
                if code == "invocation_id_mismatch"
        ));
        assert_eq!(
            sink.write(
                ToolArtifactWriteRequest {
                    invocation_id: "active".to_string(),
                    artifact_id: "large".to_string(),
                    content_type: "application/octet-stream".to_string(),
                    bytes: vec![
                        0;
                        usize::try_from(SESSION_ARTIFACT_WRITE_MAX_BYTES).expect("bound")
                            + 1
                    ],
                    metadata: serde_json::Value::Null,
                },
                test_artifact_scope("active").artifact_commit_guard()
            )
            .await,
            ToolArtifactWriteResolution::TooLarge {
                max_bytes: SESSION_ARTIFACT_WRITE_MAX_BYTES
            }
        );

        let cancelled = TurnCancelState::default();
        cancelled.cancel().await;
        let cancelled_sink =
            SessionArtifactSink::new(root.path().to_path_buf(), "cancelled", &cancelled);
        assert_eq!(
            cancelled_sink
                .write(
                    ToolArtifactWriteRequest {
                        invocation_id: "cancelled".to_string(),
                        artifact_id: "cancelled".to_string(),
                        content_type: "application/octet-stream".to_string(),
                        bytes: Vec::new(),
                        metadata: serde_json::Value::Null,
                    },
                    test_artifact_scope("cancelled").artifact_commit_guard()
                )
                .await,
            ToolArtifactWriteResolution::Cancelled
        );
    }
    #[test]
    fn server_plugin_bridge_round_trips_requests_without_async_runtime_blocking() {
        let (sender, mut requests) = mpsc::unbounded_channel();
        let request = ServiceBridgeRequest::Exchange(ToolExchangeRequest {
            invocation_id: "call".to_string(),
            exchange_id: "exchange".to_string(),
            producer_id: "test".to_string(),
            schema: "test.exchange".to_string(),
            schema_version: 1,
            payload: serde_json::Value::Null,
            response_policy: bcode_tool::ToolExchangeResponsePolicy::Required,
        });
        let worker = std::thread::spawn(move || {
            request_server_plugin_bridge(
                &sender,
                request,
                &bcode_plugin_sdk::ServiceCancellation::default(),
            )
            .expect("bridge response")
        });
        let call = requests.blocking_recv().expect("bridge request");
        call.response
            .send(Ok(ServiceBridgeResponse::Exchange(
                ToolExchangeResolution::Responded {
                    payload: serde_json::json!({"ok": true}),
                },
            )))
            .expect("bridge response delivery");

        assert!(matches!(
            worker.join().expect("bridge worker"),
            ServiceBridgeResponse::Exchange(ToolExchangeResolution::Responded { payload })
                if payload == serde_json::json!({"ok": true})
        ));
    }

