    #[test]
    fn tool_request_draft_batches_append_bytes_and_checkpoints_bounded_state() {
        let mut progress = ModelStreamProgress::default();
        progress.start_tool_call_with_presentation(
            None,
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            ToolRequestDraftPresentation {
                producer_plugin_id: Some("bcode.filesystem".to_owned()),
                schema: "bcode.filesystem.request-draft.write".to_owned(),
                schema_version: 1,
                placement: bcode_session_models::ToolContributionPlacement::Result,
            },
        );
        progress.record_tool_call_delta("call-write", "{\"path\":\"src/lib.rs\",");
        progress.record_tool_call_delta("call-write", "\"contents\":\"hello\"}");
        let first = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("first provider delta should be visible immediately");
        assert!(matches!(
            first.operation,
            bcode_session_models::ToolRequestDraftOperation::Append { offset: 0, .. }
        ));
        progress.record_tool_call_delta("call-write", &"x".repeat(1024));

        let event = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("batched request draft");
        assert_eq!(event.turn_id, "turn-1");
        assert_eq!(event.tool_call_id, "call-write");
        assert_eq!(
            event.producer_plugin_id.as_deref(),
            Some("bcode.filesystem")
        );
        assert_eq!(event.schema, "bcode.filesystem.request-draft.write");
        assert!(matches!(
            event.operation,
            bcode_session_models::ToolRequestDraftOperation::Append { offset, .. }
                if offset == first.argument_bytes
        ));
        let checkpoint = progress
            .tool_request_draft_checkpoint("turn-1", "call-write")
            .expect("request draft checkpoint");
        assert!(matches!(
            checkpoint.operation,
            bcode_session_models::ToolRequestDraftOperation::Checkpoint {
                start_offset: 0,
                ..
            }
        ));
        assert_eq!(checkpoint.argument_bytes, event.argument_bytes);
    }

    #[test]
    fn tool_request_draft_preview_is_utf8_safe_and_bounded() {
        let mut progress = ModelStreamProgress::default();
        progress.start_tool_call(
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        let delta = "é".repeat(ModelStreamProgress::MAX_TOOL_REQUEST_DRAFT_PREVIEW_BYTES);
        progress.record_tool_call_delta("call-write", &delta);
        let checkpoint = progress
            .tool_request_draft_checkpoint("turn-1", "call-write")
            .expect("bounded checkpoint");
        let emitted = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("bounded emitted checkpoint");
        let bcode_session_models::ToolRequestDraftOperation::Checkpoint {
            start_offset: emitted_start_offset,
            text: emitted_text,
        } = emitted.operation
        else {
            panic!("expected emitted checkpoint after truncation");
        };
        let bcode_session_models::ToolRequestDraftOperation::Checkpoint { start_offset, text } =
            checkpoint.operation
        else {
            panic!("expected checkpoint");
        };
        assert_eq!(emitted_start_offset, start_offset);
        assert_eq!(emitted_text, text);
        assert!(text.len() <= ModelStreamProgress::MAX_TOOL_REQUEST_DRAFT_PREVIEW_BYTES);
        assert!(start_offset > 0);
        assert!(checkpoint.truncated);
        assert!(std::str::from_utf8(text.as_bytes()).is_ok());
        let active = &progress.active_tool_calls["call-write"];
        assert!(active.pending_text.is_empty());
        assert!(!active.pending_checkpoint);
    }

    #[test]
    fn tool_request_draft_append_offsets_count_utf8_bytes() {
        let mut progress = ModelStreamProgress::default();
        progress.start_tool_call(
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        let delta = "λ".repeat(256);
        progress.record_tool_call_delta("call-write", &delta);

        let event = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("first UTF-8 append");
        assert_eq!(event.argument_bytes, delta.len());
        assert!(matches!(
            event.operation,
            bcode_session_models::ToolRequestDraftOperation::Append { offset: 0, ref text }
                if text == &delta
        ));
        let checkpoint = progress
            .tool_request_draft_checkpoint("turn-1", "call-write")
            .expect("UTF-8 checkpoint");
        assert!(matches!(
            checkpoint.operation,
            bcode_session_models::ToolRequestDraftOperation::Checkpoint {
                start_offset: 0,
                ref text,
            } if text == &delta
        ));
    }

    #[test]
    fn tool_request_drafts_support_interleaved_provider_calls() {
        let mut progress = ModelStreamProgress::default();
        progress.start_tool_call(
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        progress.start_tool_call(
            "call-edit".to_owned(),
            "filesystem.edit".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        progress.record_tool_call_delta("call-write", &"w".repeat(512));
        progress.record_tool_call_delta("call-edit", &"e".repeat(512));

        let write = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("write draft");
        let edit = progress
            .take_tool_request_draft_event("turn-1", "call-edit")
            .expect("edit draft");
        assert_eq!(write.tool_call_id, "call-write");
        assert_eq!(edit.tool_call_id, "call-edit");
        assert_eq!(progress.tool_request_draft_checkpoints("turn-1").len(), 2);
        progress.finish_tool_call("call-write");
        assert_eq!(progress.tool_request_draft_checkpoints("turn-1").len(), 1);
    }

    #[test]
    fn tool_request_draft_fragmented_utf8_and_split_escape_remain_exact() {
        let mut progress = ModelStreamProgress::default();
        progress.start_tool_call(
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        let fragments = vec![
            r#"{"path":"src/λ.rs","contents":"line\"#.to_owned(),
            r"nemoji ".to_owned(),
            "🙂".to_owned(),
            "x".repeat(512),
            r#""}"#.to_owned(),
        ];
        for fragment in &fragments {
            progress.record_tool_call_delta("call-write", fragment);
        }
        let expected = fragments.concat();
        let event = progress
            .take_tool_request_draft_event("turn-1", "call-write")
            .expect("fragmented draft");
        assert_eq!(event.argument_bytes, expected.len());
        assert!(matches!(
            event.operation,
            bcode_session_models::ToolRequestDraftOperation::Append { offset: 0, ref text }
                if text == &expected
        ));
        let checkpoint = progress
            .tool_request_draft_checkpoint("turn-1", "call-write")
            .expect("fragmented checkpoint");
        assert!(matches!(
            checkpoint.operation,
            bcode_session_models::ToolRequestDraftOperation::Checkpoint {
                start_offset: 0,
                ref text,
            } if text == &expected
        ));
    }

    #[test]
    fn tool_request_draft_provider_retry_removes_every_active_call() {
        let mut progress = ModelStreamProgress::default();
        for call_id in ["call-write", "call-edit"] {
            progress.start_tool_call(
                call_id.to_owned(),
                "filesystem.write".to_owned(),
                Some("bcode.filesystem".to_owned()),
            );
            progress.record_tool_call_delta(call_id, &"x".repeat(512));
        }
        let generations = progress
            .tool_request_draft_checkpoints("turn-1")
            .into_iter()
            .map(|draft| (draft.tool_call_id, draft.generation))
            .collect::<BTreeMap<_, _>>();

        for call_id in ["call-write", "call-edit"] {
            progress.finish_tool_call(call_id);
        }
        assert!(progress.tool_request_draft_checkpoints("turn-1").is_empty());
        progress.start_tool_call(
            "call-write".to_owned(),
            "filesystem.write".to_owned(),
            Some("bcode.filesystem".to_owned()),
        );
        assert_eq!(
            progress
                .tool_request_draft_checkpoint("turn-1", "call-write")
                .expect("retry generation")
                .generation,
            generations["call-write"].saturating_add(1)
        );
    }

