    #[test]
    fn completed_reasoning_is_taken_in_stable_order_before_tool_boundary_segment() {
        let mut outcome = ModelPollOutcome::default();
        for (activity_id, order, text) in [
            ("reasoning-later", 1, "later"),
            ("reasoning-first", 0, "first"),
        ] {
            let mut activity = ReasoningActivityAccumulator::new(activity_id.to_owned(), order);
            activity.apply(
                &bcode_session_models::ReasoningActivityEvent::PartCompleted {
                    activity_id: activity_id.to_owned(),
                    activity_order: order,
                    part_id: "summary-0".to_owned(),
                    kind: bcode_session_models::ReasoningContentKind::Summary,
                    role: bcode_session_models::ReasoningContentRole::Milestone,
                    part_order: 0,
                    text: text.to_owned(),
                },
            );
            activity.apply(&bcode_session_models::ReasoningActivityEvent::Finished {
                activity_id: activity_id.to_owned(),
                activity_order: order,
                status: bcode_session_models::ReasoningActivityStatus::Completed,
            });
            outcome
                .reasoning_activities
                .insert(activity_id.to_owned(), activity);
        }
        outcome.reasoning_activities.insert(
            "reasoning-active".to_owned(),
            ReasoningActivityAccumulator::new("reasoning-active".to_owned(), 2),
        );

        let mut completed = take_completed_reasoning_activities(&mut outcome);
        completed.sort_by_key(|activity| (activity.order, activity.activity_id.clone()));
        assert_eq!(
            completed
                .iter()
                .map(|activity| activity.activity_id.as_str())
                .collect::<Vec<_>>(),
            ["reasoning-first", "reasoning-later"]
        );
        assert_eq!(
            outcome
                .reasoning_activities
                .keys()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            ["reasoning-active"]
        );
    }

    #[test]
    fn assistant_segment_identity_rotates_only_after_commit() {
        let cancel_state = Arc::new(TurnCancelState::default());
        let mut stream =
            ModelStreamAccumulator::new(SessionId::new(), "turn-1", 0, Arc::clone(&cancel_state));
        stream.push_text("before tool");

        let first = stream
            .take_assistant_segment()
            .expect("first segment should be available");
        assert_eq!(first.segment_id, "segment-0");
        assert_eq!(first.segment_order, 0);
        assert_eq!(first.text, "before tool");

        stream.advance_segment(1);
        stream.push_text("after tool");
        let second = stream.finish().expect("second segment should be available");
        assert_eq!(second.segment_id, "segment-1");
        assert_eq!(second.segment_order, 1);
        assert_eq!(second.text, "after tool");
    }

    #[test]
    fn reasoning_activity_accumulator_preserves_part_boundaries_and_replacement() {
        let mut streamed = ReasoningActivityAccumulator::new("reasoning-stream".to_owned(), 0);
        for text in ["Draft ", "continued"] {
            streamed.apply(&bcode_session_models::ReasoningActivityEvent::PartDelta {
                activity_id: "reasoning-stream".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: text.to_owned(),
            });
        }
        assert_eq!(
            streamed
                .finish(bcode_session_models::ReasoningActivityStatus::Completed)
                .parts[0]
                .text,
            "Draft continued"
        );

        let mut activity = ReasoningActivityAccumulator::new("reasoning-1".to_owned(), 0);
        for event in [
            bcode_session_models::ReasoningActivityEvent::PartDelta {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: "Draft ".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::PartDelta {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: "continued".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::PartCompleted {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: "Complete summary".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::PartDelta {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: " duplicate late delta".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::PartCompleted {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "raw-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Raw,
                role: bcode_session_models::ReasoningContentRole::Detail,
                part_order: 1,
                text: "Raw detail".to_owned(),
            },
        ] {
            activity.apply(&event);
        }

        let activity = activity.finish(bcode_session_models::ReasoningActivityStatus::Completed);
        assert_eq!(activity.parts.len(), 2);
        assert_eq!(activity.parts[0].text, "Complete summary");
        assert_eq!(activity.parts[1].text, "Raw detail");
    }

    #[test]
    fn interrupted_reasoning_retains_only_authoritative_completed_parts() {
        let mut activity = ReasoningActivityAccumulator::new("reasoning-1".to_owned(), 0);
        for event in [
            bcode_session_models::ReasoningActivityEvent::PartCompleted {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "summary-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Summary,
                role: bcode_session_models::ReasoningContentRole::Milestone,
                part_order: 0,
                text: "Completed milestone".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::PartDelta {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                part_id: "raw-0".to_owned(),
                kind: bcode_session_models::ReasoningContentKind::Raw,
                role: bcode_session_models::ReasoningContentRole::Detail,
                part_order: 1,
                text: "partial detail".to_owned(),
            },
            bcode_session_models::ReasoningActivityEvent::Finished {
                activity_id: "reasoning-1".to_owned(),
                activity_order: 0,
                status: bcode_session_models::ReasoningActivityStatus::Completed,
            },
        ] {
            activity.apply(&event);
        }

        let activity = activity.finish(bcode_session_models::ReasoningActivityStatus::Interrupted);
        assert_eq!(
            activity.status,
            bcode_session_models::ReasoningActivityStatus::Interrupted
        );
        assert_eq!(activity.parts.len(), 1);
        assert_eq!(activity.parts[0].text, "Completed milestone");
    }

    #[test]
    fn reasoning_activity_accumulator_preserves_opaque_token_evidence() {
        let mut activity = ReasoningActivityAccumulator::new(
            "reasoning-tokens:provider-turn".to_owned(),
            u32::MAX,
        );
        activity.opaque = true;
        activity.status = Some(bcode_session_models::ReasoningActivityStatus::Completed);

        let activity = activity.finish(bcode_session_models::ReasoningActivityStatus::Completed);
        assert!(activity.opaque);
        assert!(activity.parts.is_empty());
        assert_eq!(
            activity.status,
            bcode_session_models::ReasoningActivityStatus::Completed
        );
    }

    #[test]
    fn model_poll_progress_requires_meaningful_stream_events() {
        assert!(model_event_is_progress(&ProviderTurnEvent::TextDelta {
            text: "hello".to_string(),
        }));
        assert!(model_event_is_progress(
            &ProviderTurnEvent::ReasoningDelta {
                text: "thinking".to_string(),
            }
        ));
        assert!(model_event_is_progress(&ProviderTurnEvent::ToolCallDelta {
            call_id: "call-test".to_string(),
            delta: "{\"path\"".to_string(),
        }));
        assert!(model_event_is_progress(
            &ProviderTurnEvent::ToolCallStarted {
                call_id: "call-test".to_string(),
                name: "filesystem.read".to_string(),
            }
        ));
        assert!(model_event_is_progress(
            &ProviderTurnEvent::ToolCallFinished {
                call: test_tool_call(),
            }
        ));

        assert!(!model_event_is_progress(&ProviderTurnEvent::TextDelta {
            text: String::new(),
        }));
        assert!(!model_event_is_progress(
            &ProviderTurnEvent::ToolCallDelta {
                call_id: "call-test".to_string(),
                delta: String::new(),
            }
        ));
        assert!(!model_event_is_progress(&ProviderTurnEvent::Usage {
            usage: bcode_model::TokenUsage::default(),
        }));
        assert!(!model_event_is_progress(
            &ProviderTurnEvent::ProviderMetadata {
                key: "response_id".to_string(),
                value: "resp-test".to_string(),
            }
        ));
        assert!(!model_event_is_progress(&ProviderTurnEvent::Warning {
            message: "warning".to_string(),
        }));
    }

