    #[test]
    fn prompt_cache_auto_marks_stable_sections_only() {
        let mut messages = Vec::new();

        let hints = plan_prompt_cache(&mut messages, bcode_model::PromptCacheMode::Auto);

        assert!(hints.cache_system_prompt);
        assert!(hints.cache_tools);
        assert_eq!(messages.len(), 0);
    }

    #[test]
    fn prompt_cache_aggressive_marks_conversation_prefix() {
        let mut messages = (0..6)
            .map(|index| ModelMessage {
                role: MessageRole::User,
                content: vec![ContentBlock::Text {
                    text: format!("message {index}"),
                }],
            })
            .collect::<Vec<_>>();

        let hints = plan_prompt_cache(&mut messages, bcode_model::PromptCacheMode::Aggressive);

        assert!(hints.cache_system_prompt);
        assert!(matches!(
            messages[3].content.last(),
            Some(ContentBlock::CachePoint { .. })
        ));
        assert!(!matches!(
            messages[5].content.last(),
            Some(ContentBlock::CachePoint { .. })
        ));
    }

    #[test]
    #[allow(clippy::too_many_lines)]
    fn presentation_and_exchange_payloads_are_excluded_from_model_context() {
        let session_id = SessionId::new();
        let session_event = |sequence, kind| bcode_session_models::SessionEvent {
            schema_version: CURRENT_SESSION_EVENT_SCHEMA_VERSION,
            sequence,
            timestamp_ms: sequence,
            session_id,
            provenance: None,
            kind,
        };
        let events = vec![
            session_event(
                1,
                SessionEventKind::ToolCallRequested {
                    tool_call_id: "call-1".to_owned(),
                    producer_plugin_id: Some("test.plugin".to_owned()),
                    tool_name: "test.tool".to_owned(),
                    arguments_json: r#"{"model_visible":"safe-argument"}"#.to_owned(),
                    working_directory: None,
                },
            ),
            session_event(
                3,
                SessionEventKind::ToolExchangeRequested {
                    request: bcode_session_models::ToolExchangeRequest {
                        invocation_id: "call-1".to_owned(),
                        exchange_id: "interaction-1".to_owned(),
                        producer_id: "test.plugin".to_owned(),
                        schema: "test.exchange".to_owned(),
                        schema_version: 1,
                        payload: serde_json::json!({"private": "EXCHANGE_REQUEST_PRIVATE"}),
                        response_policy: bcode_session_models::ToolExchangeResponsePolicy::Required,
                    },
                },
            ),
            session_event(
                4,
                SessionEventKind::ToolExchangeResolved {
                    event: bcode_session_models::ToolExchangeResolutionEvent {
                        invocation_id: "call-1".to_owned(),
                        exchange_id: "interaction-1".to_owned(),
                        resolution: bcode_session_models::ToolExchangeResolution::Responded {
                            payload: serde_json::json!({"private": "EXCHANGE_RESPONSE_PRIVATE"}),
                        },
                    },
                },
            ),
            session_event(
                5,
                SessionEventKind::PermissionRequested {
                    permission_id: "permission-1".to_owned(),
                    tool_call_id: "call-1".to_owned(),
                    producer_plugin_id: Some("test.plugin".to_owned()),
                    tool_name: "test.tool".to_owned(),
                    arguments_json: "PERMISSION_PRESENTATION_PRIVATE".to_owned(),
                    batch: None,
                    policy_source: Some("PRIVATE_POLICY_SOURCE".to_owned()),
                    policy_reason: Some("PRIVATE_POLICY_REASON".to_owned()),
                },
            ),
            session_event(
                6,
                SessionEventKind::PluginStatusNote {
                    plugin_id: "test.plugin".to_owned(),
                    note_id: "private-note".to_owned(),
                    text: "PLUGIN_STATUS_PRIVATE".to_owned(),
                    metadata: BTreeMap::from([(
                        "private".to_owned(),
                        serde_json::json!("PLUGIN_METADATA_PRIVATE"),
                    )]),
                },
            ),
            session_event(
                7,
                SessionEventKind::ToolInvocationLifecycle {
                    event: bcode_session_models::ToolInvocationLifecycleEvent {
                        invocation_id: "call-1".to_owned(),
                        sequence: 1,
                        stage: bcode_session_models::ToolInvocationLifecycleStage::Waiting,
                        message: Some("LIFECYCLE_PRIVATE".to_owned()),
                        metadata: serde_json::json!({"private": "LIFECYCLE_METADATA_PRIVATE"}),
                    },
                },
            ),
            session_event(
                8,
                SessionEventKind::ToolContribution {
                    event: bcode_session_models::ToolContributionEvent {
                        invocation_id: "call-1".to_owned(),
                        contribution_id: "private".to_owned(),
                        sequence: 1,
                        producer_id: "test.plugin".to_owned(),
                        schema: "test.unknown".to_owned(),
                        schema_version: 99,
                        operation: bcode_session_models::ToolContributionOperation::Upsert,
                        persistence: bcode_session_models::ToolContributionPersistence::Durable,
                        artifact: None,
                        payload: serde_json::json!({"private": "CONTRIBUTION_PRIVATE"}),
                    },
                },
            ),
            session_event(
                9,
                SessionEventKind::ToolExchangeRequested {
                    request: bcode_session_models::ToolExchangeRequest {
                        invocation_id: "call-1".to_owned(),
                        exchange_id: "private-exchange".to_owned(),
                        producer_id: "test.plugin".to_owned(),
                        schema: "test.private-exchange".to_owned(),
                        schema_version: 1,
                        payload: serde_json::json!({"private": "GENERIC_EXCHANGE_REQUEST_PRIVATE"}),
                        response_policy: bcode_session_models::ToolExchangeResponsePolicy::Required,
                    },
                },
            ),
            session_event(
                10,
                SessionEventKind::ToolExchangeResolved {
                    event: bcode_session_models::ToolExchangeResolutionEvent {
                        invocation_id: "call-1".to_owned(),
                        exchange_id: "private-exchange".to_owned(),
                        resolution: bcode_session_models::ToolExchangeResolution::Responded {
                            payload: serde_json::json!({"private": "GENERIC_EXCHANGE_RESPONSE_PRIVATE"}),
                        },
                    },
                },
            ),
            session_event(
                11,
                SessionEventKind::ToolInvocationResultRecorded {
                    record: bcode_session_models::ToolInvocationResultRecord {
                        invocation_id: "call-1".to_owned(),
                        model_output: "safe-result".to_owned(),
                        is_error: false,
                        presentation: None,
                        result: None,
                    },
                },
            ),
        ];

        let messages = session_events_to_model_messages(&events);
        let encoded = serde_json::to_string(&messages).expect("model messages serialize");
        assert!(encoded.contains("safe-argument"));
        assert!(encoded.contains("safe-result"));
        for marker in [
            "REQUEST_VISUAL_PRIVATE",
            "LEGACY_REQUEST_PRESENTATION_PRIVATE",
            "EXCHANGE_REQUEST_PRIVATE",
            "EXCHANGE_RESPONSE_PRIVATE",
            "PERMISSION_PRESENTATION_PRIVATE",
            "PRIVATE_POLICY_SOURCE",
            "PRIVATE_POLICY_REASON",
            "PLUGIN_STATUS_PRIVATE",
            "PLUGIN_METADATA_PRIVATE",
            "LIFECYCLE_PRIVATE",
            "LIFECYCLE_METADATA_PRIVATE",
            "CONTRIBUTION_PRIVATE",
            "GENERIC_EXCHANGE_REQUEST_PRIVATE",
            "GENERIC_EXCHANGE_RESPONSE_PRIVATE",
        ] {
            assert!(!encoded.contains(marker), "model context leaked {marker}");
        }
    }

    #[test]
    fn positioned_tool_round_is_reconstructed_as_structured_model_context() {
        let session_id = SessionId::new();
        let turn_id = "turn-1".to_owned();
        let history = vec![
            session_event(
                session_id,
                1,
                SessionEventKind::PositionedToolCallRequested {
                    turn_id: turn_id.clone(),
                    output_position: bcode_session_models::TurnOutputPosition::new(0),
                    tool_call_id: "call-1".to_owned(),
                    tool_name: "filesystem.read".to_owned(),
                    arguments_json: r#"{"path":"README.md"}"#.to_owned(),
                    producer_plugin_id: Some("bcode.filesystem".to_owned()),
                    working_directory: None,
                },
            ),
            session_event(
                session_id,
                2,
                SessionEventKind::ToolInvocationResultRecorded {
                    record: bcode_session_models::ToolInvocationResultRecord {
                        invocation_id: "call-1".to_owned(),
                        model_output: "contents".to_owned(),
                        is_error: false,
                        presentation: None,
                        result: None,
                    },
                },
            ),
            session_event(
                session_id,
                3,
                SessionEventKind::PositionedAssistantResponseSegment {
                    turn_id,
                    output_position: bcode_session_models::TurnOutputPosition::new(1),
                    segment_id: "segment-0".to_owned(),
                    segment_order: 0,
                    text: "done".to_owned(),
                },
            ),
        ];

        let messages = session_events_to_model_messages(&history);
        assert_eq!(messages.len(), 3);
        assert_eq!(messages[0].role, MessageRole::Assistant);
        assert!(matches!(
            messages[0].content.as_slice(),
            [ContentBlock::ToolCall { .. }]
        ));
        assert_eq!(messages[1].role, MessageRole::Tool);
        assert_eq!(messages[2].role, MessageRole::Assistant);
        assert!(matches!(
            messages[2].content.as_slice(),
            [ContentBlock::Text { text }] if text == "done"
        ));
    }

    #[test]
    fn completed_assistant_segment_is_model_visible_and_workflow_addressable() {
        let session_id = SessionId::new();
        let turn_id = "turn-1".to_owned();
        let history = vec![
            bcode_session_models::SessionEvent {
                schema_version: CURRENT_SESSION_EVENT_SCHEMA_VERSION,
                sequence: 1,
                timestamp_ms: 1,
                session_id,
                provenance: None,
                kind: SessionEventKind::ModelTurnStarted {
                    turn_id: turn_id.clone(),
                },
            },
            bcode_session_models::SessionEvent {
                schema_version: CURRENT_SESSION_EVENT_SCHEMA_VERSION,
                sequence: 2,
                timestamp_ms: 2,
                session_id,
                provenance: None,
                kind: SessionEventKind::AssistantResponseSegment {
                    turn_id: turn_id.clone(),
                    segment_id: "segment-0".to_owned(),
                    segment_order: 0,
                    text: "durable answer".to_owned(),
                },
            },
            bcode_session_models::SessionEvent {
                schema_version: CURRENT_SESSION_EVENT_SCHEMA_VERSION,
                sequence: 3,
                timestamp_ms: 3,
                session_id,
                provenance: None,
                kind: SessionEventKind::ModelTurnFinished {
                    turn_id: turn_id.clone(),
                    outcome: ModelTurnOutcome::Completed,
                    message: None,
                },
            },
        ];

        let message = non_tool_session_event_to_model_message(&history[1])
            .expect("completed segment belongs in model context");
        assert_eq!(message.role, MessageRole::Assistant);
        assert!(matches!(
            message.content.as_slice(),
            [ContentBlock::Text { text }] if text == "durable answer"
        ));
        assert_eq!(
            workflow_turn_output(&history, &turn_id).as_deref(),
            Some("durable answer")
        );
    }

