    #[tokio::test]
    async fn retained_presentation_hydrates_attach_and_active_only_is_cleared_on_close() {
        let workspace = tempfile::tempdir().expect("presentation hydration workspace");
        let sessions = SessionManager::persistent(workspace.path().join("sessions"))
            .expect("presentation hydration session manager");
        let state = test_server_state(sessions);
        let session_id = SessionId::new();
        let update = |retention| bcode_tool::ToolPresentationUpdate {
            invocation_id: "call-1".to_owned(),
            producer_id: "test.plugin".to_owned(),
            generation: 0,
            revision: 1,
            identity: bcode_tool::ToolPresentationIdentity::Primary,
            retention,
            schema: "test.presentation".to_owned(),
            schema_version: 1,
            artifact: None,
            payload: serde_json::json!({"value": 1}),
        };

        publish_plugin_tool_presentation_update(
            &state,
            session_id,
            "call-1",
            "test.plugin",
            update(bcode_tool::ToolPresentationRetention::RetainLatest),
        )
        .await
        .expect("retained update accepted");
        let snapshots = active_presentation_snapshot_events(&state, session_id);
        assert_eq!(snapshots.len(), 1);
        assert!(matches!(
            &snapshots[0].kind,
            SessionLiveEventKind::ToolPresentationUpdated { update }
                if update.generation == 0 && update.revision == 1
        ));
        close_tool_presentation_update_scope(&state, session_id, "call-1");
        assert_eq!(
            active_presentation_snapshot_events(&state, session_id).len(),
            1
        );

        let second_session = SessionId::new();
        publish_plugin_tool_presentation_update(
            &state,
            second_session,
            "call-2",
            "test.plugin",
            bcode_tool::ToolPresentationUpdate {
                invocation_id: "call-2".to_owned(),
                ..update(bcode_tool::ToolPresentationRetention::ActiveOnly)
            },
        )
        .await
        .expect("active-only update accepted");
        assert_eq!(
            active_presentation_snapshot_events(&state, second_session).len(),
            1
        );
        close_tool_presentation_update_scope(&state, second_session, "call-2");
        assert!(active_presentation_snapshot_events(&state, second_session).is_empty());
    }

    #[test]
    fn presentation_update_registry_enforces_owner_bounds_and_absorbing_closure() {
        let workspace = tempfile::tempdir().expect("presentation registry workspace");
        let sessions = SessionManager::persistent(workspace.path().join("sessions"))
            .expect("presentation registry session manager");
        let state = test_server_state(sessions);
        let session_id = SessionId::new();
        let update = bcode_tool::ToolPresentationUpdate {
            invocation_id: "call-1".to_owned(),
            producer_id: "test.plugin".to_owned(),
            generation: 0,
            revision: 1,
            identity: bcode_tool::ToolPresentationIdentity::Primary,
            retention: bcode_tool::ToolPresentationRetention::RetainLatest,
            schema: "test.presentation".to_owned(),
            schema_version: 1,
            artifact: None,
            payload: serde_json::json!({"value": 1}),
        };

        assert_eq!(
            accept_tool_presentation_update(
                &state,
                session_id,
                "other-call",
                "test.plugin",
                &update,
            ),
            Err(bcode_tool::ToolPresentationUpdateError::InvocationMismatch)
        );
        assert_eq!(
            accept_tool_presentation_update(&state, session_id, "call-1", "other.plugin", &update,),
            Err(bcode_tool::ToolPresentationUpdateError::ProducerMismatch)
        );
        let oversized = bcode_tool::ToolPresentationUpdate {
            payload: serde_json::json!({
                "value": "x".repeat(MAX_ACTIVE_CONTRIBUTION_BYTES)
            }),
            ..update.clone()
        };
        assert!(matches!(
            accept_tool_presentation_update(
                &state,
                session_id,
                "call-1",
                "test.plugin",
                &oversized,
            ),
            Err(bcode_tool::ToolPresentationUpdateError::TooLarge {
                maximum: MAX_ACTIVE_CONTRIBUTION_BYTES,
                ..
            })
        ));
        accept_tool_presentation_update(&state, session_id, "call-1", "test.plugin", &update)
            .expect("first update accepted");
        assert_eq!(
            accept_tool_presentation_update(&state, session_id, "call-1", "test.plugin", &update,),
            Err(bcode_tool::ToolPresentationUpdateError::StaleRevision)
        );
        assert_eq!(
            state
                .presentation_update_scopes
                .lock()
                .expect("presentation scopes")
                .get(&(session_id, "call-1".to_owned()))
                .and_then(|scope| {
                    scope.highest_revision(&bcode_tool::ToolPresentationIdentity::Primary)
                }),
            Some(1)
        );
        close_tool_presentation_update_scope(&state, session_id, "call-1");
        assert_eq!(
            state
                .presentation_update_scopes
                .lock()
                .expect("presentation scopes")
                .get(&(session_id, "call-1".to_owned()))
                .and_then(|scope| {
                    scope.highest_revision(&bcode_tool::ToolPresentationIdentity::Primary)
                }),
            Some(1)
        );
        assert_eq!(
            accept_tool_presentation_update(
                &state,
                session_id,
                "call-1",
                "test.plugin",
                &bcode_tool::ToolPresentationUpdate {
                    revision: 2,
                    ..update
                },
            ),
            Err(bcode_tool::ToolPresentationUpdateError::Closed)
        );
    }

    #[tokio::test]
    async fn workflow_computation_deadline_and_cancellation_are_bounded_and_cleaned_up() {
        let state = Arc::new(test_server_state(SessionManager::default()));
        let timeout = run_workflow_computation(
            state.as_ref(),
            bcode_ipc::WorkflowComputationControl {
                operation_id: "timeout-test".to_string(),
                timeout_ms: 1,
            },
            "fallback".to_string(),
            || {
                std::thread::sleep(Duration::from_millis(50));
                1_u8
            },
        )
        .await
        .expect_err("computation must time out");
        assert!(matches!(
            timeout,
            ServerError::WorkflowComputationTimedOut(_)
        ));
        assert!(
            state
                .workflow_computations
                .lock()
                .expect("computations")
                .is_empty()
        );

        let cancellation_state = Arc::clone(&state);
        let operation = tokio::spawn(async move {
            run_workflow_computation(
                cancellation_state.as_ref(),
                bcode_ipc::WorkflowComputationControl {
                    operation_id: "cancel-test".to_string(),
                    timeout_ms: 1_000,
                },
                "fallback".to_string(),
                || {
                    std::thread::sleep(Duration::from_millis(50));
                    1_u8
                },
            )
            .await
        });
        tokio::task::yield_now().await;
        assert!(cancel_workflow_computation(state.as_ref(), "cancel-test"));
        let cancelled = operation
            .await
            .expect("join cancellation test")
            .expect_err("explicit cancellation must win");
        assert!(matches!(
            cancelled,
            ServerError::WorkflowComputationCancelled(_)
        ));
        assert!(
            state
                .workflow_computations
                .lock()
                .expect("computations")
                .is_empty()
        );
    }

    #[test]
    fn authored_workflow_application_authorization_uses_canonical_facts_and_precedes_mutation() {
        let mut state = test_server_state(SessionManager::default());
        let workflow_id = "workflow/authorization-test".to_string();
        let facts = WorkflowApplicationOperationFacts {
            version: bcode_workflow::WORKFLOW_APPLICATION_OPERATION_FACTS_VERSION,
            operation: bcode_workflow::WorkflowApplicationOperation::CreateWorkflow,
            actor: bcode_workflow::WorkflowApplicationActor {
                kind: bcode_workflow::WorkflowApplicationActorKind::LocalClient,
                actor_id: ClientId::new().to_string(),
            },
            workflow_id: workflow_id.clone(),
            draft_id: None,
            revision: None,
            preset_id: None,
            producer: None,
            requirements: bcode_workflow::WorkflowRequirementSummary::default(),
            effects: bcode_workflow::WorkflowEffectSummary::default(),
            activates: false,
            executes: false,
        };
        state.workflow_application_authorization = WorkflowApplicationAuthorizationPolicy {
            evaluator: Arc::new(|facts| {
                assert_eq!(
                    facts.operation,
                    bcode_workflow::WorkflowApplicationOperation::CreateWorkflow
                );
                assert_eq!(
                    facts.actor.kind,
                    bcode_workflow::WorkflowApplicationActorKind::LocalClient
                );
                WorkflowApplicationAuthorizationDecision::Deny {
                    reason: "test policy denial".to_string(),
                }
            }),
        };

        let error = state
            .authorize_workflow_application_operation(&facts)
            .expect_err("policy must deny operation");
        assert!(matches!(
            error,
            ServerError::WorkflowApplicationOperationUnauthorized(reason)
                if reason == "test policy denial"
        ));
        assert!(
            state
                .workflow_store
                .lock()
                .expect("workflow store")
                .authored_workflow(&workflow_id)
                .expect("read workflow")
                .is_none(),
            "authorization denial must occur before any store mutation"
        );
    }

    #[test]
    fn publication_authorization_does_not_authorize_execution() {
        let mut state = test_server_state(SessionManager::default());
        state.workflow_application_authorization = WorkflowApplicationAuthorizationPolicy {
            evaluator: Arc::new(|facts| {
                if facts.operation == bcode_workflow::WorkflowApplicationOperation::PublishDraft {
                    assert!(!facts.executes);
                    WorkflowApplicationAuthorizationDecision::Allow
                } else {
                    WorkflowApplicationAuthorizationDecision::Deny {
                        reason: "execution requires a separate authorization decision".to_string(),
                    }
                }
            }),
        };
        let client_id = ClientId::new();
        let common = |operation, executes| LocalWorkflowApplicationOperationRequest {
            operation,
            workflow_id: "workflow/publication-is-not-execution".to_string(),
            draft_id: Some("draft".to_string()),
            revision: None,
            preset_id: None,
            producer: None,
            requirements: bcode_workflow::WorkflowRequirementSummary::default(),
            effects: bcode_workflow::WorkflowEffectSummary::default(),
            activates: false,
            executes,
        };
        state
            .authorize_local_workflow_application_operation(
                client_id,
                common(
                    bcode_workflow::WorkflowApplicationOperation::PublishDraft,
                    false,
                ),
            )
            .expect("publication authorization");
        assert!(
            state
                .authorize_local_workflow_application_operation(
                    client_id,
                    common(
                        bcode_workflow::WorkflowApplicationOperation::StartRevision,
                        true
                    ),
                )
                .is_err()
        );
    }

    #[test]
    fn local_application_authorization_ignores_untrusted_producer_kind() {
        let state = test_server_state(SessionManager::default());
        let client_id = ClientId::new();
        let authorize = |producer| {
            state.authorize_local_workflow_application_operation(
                client_id,
                LocalWorkflowApplicationOperationRequest {
                    operation: bcode_workflow::WorkflowApplicationOperation::CreateWorkflow,
                    workflow_id: "workflow/producer-neutral".to_string(),
                    draft_id: None,
                    revision: None,
                    preset_id: None,
                    producer: Some(producer),
                    requirements: bcode_workflow::WorkflowRequirementSummary::default(),
                    effects: bcode_workflow::WorkflowEffectSummary::default(),
                    activates: false,
                    executes: false,
                },
            )
        };
        let sdk = authorize(bcode_workflow::WorkflowProducerProvenance {
            kind: bcode_workflow::WorkflowProducerKind::Sdk,
            producer_id: Some("portable-sdk".to_string()),
            source_revision: None,
        })
        .expect("sdk producer");
        let plugin = authorize(bcode_workflow::WorkflowProducerProvenance {
            kind: bcode_workflow::WorkflowProducerKind::Plugin,
            producer_id: Some("example.generator".to_string()),
            source_revision: None,
        })
        .expect("plugin producer");
        assert_eq!(sdk.actor, plugin.actor);
        assert_eq!(sdk.operation, plugin.operation);
        assert_ne!(sdk.producer, plugin.producer);
    }

