    #[tokio::test]
    async fn workflow_and_manual_turns_share_one_fifo_runtime_queue() {
        let sessions = SessionManager::default();
        let session = sessions
            .create_session(Some("queue".to_owned()), PathBuf::from("."))
            .await
            .expect("session");
        let session_id = session.id;
        let (sender, mut receiver) = mpsc::channel(4);
        let queued_followups = AtomicUsize::new(0);
        let event = |sequence, text: &str, priority| bcode_session_models::SessionEvent {
            schema_version: bcode_session_models::CURRENT_SESSION_EVENT_SCHEMA_VERSION,
            session_id,
            sequence,
            timestamp_ms: sequence,
            provenance: None,
            kind: SessionEventKind::UserMessage {
                client_id: ClientId::new(),
                text: text.to_string(),
                admission: bcode_session_models::TurnAdmissionMetadata {
                    priority,
                    ..bcode_session_models::TurnAdmissionMetadata::default()
                },
            },
        };
        let ownership_one = sessions
            .acquire_session_ownership(
                session_id,
                bcode_session::SessionOwnershipKind::QueuedCommand,
            )
            .await
            .expect("first queue ownership");
        let ownership_two = sessions
            .acquire_session_ownership(
                session_id,
                bcode_session::SessionOwnershipKind::QueuedCommand,
            )
            .await
            .expect("second queue ownership");
        let command = |event, ownership| FollowupCommand::ExecuteTurn {
            client_id: ClientId::new(),
            runtime_context: None,
            user_event: Box::new(event),
            queued_steering: None,
            cancel_state: None,
            completion: None,
            ownership,
        };
        queued_followups.fetch_add(1, Ordering::AcqRel);
        sender
            .send(command(
                event(1, "manual", TurnPriority::Interactive),
                ownership_one,
            ))
            .await
            .expect("manual");
        queued_followups.fetch_add(1, Ordering::AcqRel);
        sender
            .send(command(
                event(2, "loop", TurnPriority::Background),
                ownership_two,
            ))
            .await
            .expect("loop");
        for expected in [
            ("manual", TurnPriority::Interactive),
            ("loop", TurnPriority::Background),
        ] {
            let Some(RuntimeQueueCommand::Followup(command)) = next_runtime_queue_command(
                &mut mpsc::channel(1).1,
                &mut receiver,
                &queued_followups,
            )
            .await
            else {
                panic!("expected queued turn");
            };
            let FollowupCommand::ExecuteTurn { user_event, .. } = *command else {
                panic!("expected turn command");
            };
            let SessionEventKind::UserMessage {
                text, admission, ..
            } = user_event.kind
            else {
                panic!("expected user event");
            };
            assert_eq!((text.as_str(), admission.priority), expected);
        }
        assert_eq!(queued_followups.load(Ordering::Acquire), 0);
    }

    #[tokio::test]
    async fn existing_admission_does_not_enqueue_duplicate_turn() {
        let sessions = SessionManager::default();
        let session = sessions
            .create_session(Some("existing".to_string()), PathBuf::from("."))
            .await
            .expect("session");
        let state = Arc::new(test_server_state_with_fake_provider(sessions));
        let dispatch_identity = "existing-dispatch".to_string();
        let metadata = bcode_session_models::TurnAdmissionMetadata {
            origin: Some(TurnOrigin {
                producer: "bcode.workflow".to_string(),
                correlation_id: Some(dispatch_identity.clone()),
                display_label: None,
            }),
            priority: TurnPriority::Background,
            idempotency_key: Some(dispatch_identity),
            execution: TurnExecutionOptions::default(),
        };
        let first = submit_session_model_turn_with_admission(
            &state,
            session.id,
            "first".to_string(),
            None,
            metadata.clone(),
            None,
        )
        .await
        .expect("first");
        assert!(matches!(first, SubmittedModelTurn::Started { .. }));
        let second = submit_session_model_turn_with_admission(
            &state,
            session.id,
            "first".to_string(),
            None,
            metadata,
            None,
        )
        .await
        .expect("existing");
        assert!(matches!(second, SubmittedModelTurn::Existing(_)));
        let history = state
            .sessions
            .session_history(session.id)
            .await
            .expect("history");
        assert_eq!(
            history
                .iter()
                .filter(|event| matches!(event.kind, SessionEventKind::UserMessage { .. }))
                .count(),
            1
        );
    }

