    #[tokio::test]
    async fn workflow_runtime_work_registers_parent_and_node_relationships() {
        let sessions = SessionManager::default();
        let session = sessions
            .create_session(Some("workflow".to_string()), PathBuf::from("."))
            .await
            .expect("session");
        let state = test_server_state(sessions);
        let node_cancelled = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        {
            let definition = bcode_workflow::WorkflowBuilder::new(
                "runtime-work",
                bcode_workflow::Step::task("node", |value: u32, _context| async move { Ok(value) }),
            )
            .build()
            .expect("workflow")
            .definition()
            .clone();
            let mut store = state
                .workflow_store
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner);
            store
                .persist_definition("runtime-work", 1, &definition)
                .expect("definition");
            store
                .create_run(&bcode_workflow_store::NewWorkflowRun {
                    run_id: "run-1".to_string(),
                    definition_id: "runtime-work".to_string(),
                    definition_version: 1,
                    workspace_snapshot: "snapshot-1".to_string(),
                    parent_session_id: Some(session.id.to_string()),
                    binding: None,
                    authored_provenance: None,
                    input: Some(serde_json::json!(1)),
                    created_at_ms: 1,
                    limits: bcode_workflow_store::WorkflowRunLimits::default(),
                })
                .expect("run");
        }
        let run_work_id =
            register_workflow_runtime_work(&state, session.id, "run-1", "workflow run".to_string())
                .await;
        let node_work_id = register_workflow_node_runtime_work(
            &state,
            session.id,
            &run_work_id,
            "dispatch-1",
            "workflow node".to_string(),
            CancellationHandle::Test(Arc::clone(&node_cancelled)),
        )
        .await;

        let history = state
            .sessions
            .session_history(session.id)
            .await
            .expect("history");
        assert!(history.iter().any(|event| matches!(
            &event.kind,
            SessionEventKind::RuntimeWorkStarted {
                work_id,
                kind: RuntimeWorkKind::Workflow,
                parent_work_id: None,
                ..
            } if work_id == &run_work_id
        )));
        assert!(history.iter().any(|event| matches!(
            &event.kind,
            SessionEventKind::RuntimeWorkStarted {
                work_id,
                kind: RuntimeWorkKind::WorkflowNode,
                parent_work_id: Some(parent),
                ..
            } if work_id == &node_work_id && parent == &run_work_id
        )));
        assert!(
            cancel_registered_runtime_work(&state, session.id, run_work_id, None).await,
            "parent workflow cancellation should recursively signal its node"
        );
        tokio::time::timeout(Duration::from_secs(1), async {
            loop {
                let cancelled = state
                    .workflow_store
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .run_summary("run-1")
                    .expect("summary")
                    .expect("run")
                    .cancellation_requested_at_ms
                    .is_some();
                if node_cancelled.load(std::sync::atomic::Ordering::SeqCst) == 1 && cancelled {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("parent and node cancellation");
    }

