    #[tokio::test]
    async fn strict_provider_native_failure_preserves_exact_uncompacted_context() {
        let sessions = SessionManager::default();
        let summary = sessions
            .create_session(
                Some("strict native failure".to_owned()),
                test_working_directory(),
            )
            .await
            .expect("session should be created");
        let session_id = summary.id;
        for text in ["first turn", "second turn", "active turn"] {
            sessions
                .append_event(
                    session_id,
                    SessionEventKind::UserMessage {
                        client_id: ClientId::new(),
                        text: text.to_string(),
                        admission: bcode_session_models::TurnAdmissionMetadata::default(),
                    },
                )
                .await
                .expect("append user turn");
            sessions
                .append_event(
                    session_id,
                    SessionEventKind::AssistantMessage {
                        text: format!("response to {text}"),
                    },
                )
                .await
                .expect("append assistant turn");
        }
        let before = sessions
            .model_context_events(session_id)
            .await
            .expect("context before failure");
        let mut state = test_server_state_with_fake_provider(sessions);
        state.auto_compaction.keep_recent_tokens = 1;
        state.auto_compaction.backend = bcode_config::CompactionBackend::ProviderNative;
        let selection = SessionModelSelection {
            provider_plugin_id: Some("bcode.fake-provider".to_string()),
            requested_model_id: None,
            model_id: Some("fake-model".to_string()),
            provider_context: bcode_model::ProviderRequestContext {
                settings: BTreeMap::from([
                    ("fake_native_compaction".to_string(), "true".to_string()),
                    ("fake_compaction_failure".to_string(), "true".to_string()),
                ]),
                ..bcode_model::ProviderRequestContext::default()
            },
            ..SessionModelSelection::default()
        };

        let Err(error) = compact_session_context_with_limit(
            &state,
            session_id,
            &selection,
            None,
            None,
            &TurnCancelState::default(),
            None,
        )
        .await
        else {
            panic!("strict provider-native failure must not fall back");
        };
        assert!(matches!(error, CompactionError::Provider(_)));
        let after = state
            .sessions
            .model_context_events(session_id)
            .await
            .expect("context after failure");
        let before_non_trace = before
            .iter()
            .filter(|event| !matches!(event.kind, SessionEventKind::TraceEvent { .. }))
            .collect::<Vec<_>>();
        let after_non_trace = after
            .iter()
            .filter(|event| !matches!(event.kind, SessionEventKind::TraceEvent { .. }))
            .collect::<Vec<_>>();
        assert_eq!(after_non_trace, before_non_trace);
        assert!(after.iter().any(|event| matches!(
            &event.kind,
            SessionEventKind::TraceEvent { trace }
                if trace.phase == SessionTracePhase::ContextCompactionFinished
                    && matches!(
                        &trace.payload,
                        SessionTracePayload::ContextCompaction {
                            compacted: false,
                            ..
                        }
                    )
        )));
        assert!(!after.iter().any(|event| matches!(
            event.kind,
            SessionEventKind::ContextCompacted { .. }
                | SessionEventKind::ProviderContextCompacted { .. }
        )));
    }

